    ('85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Quiz — Une aire, une primitive, une moyenne', 'Maths', 'Tle', 'Calcul intégral', '4eaeced0-2a9a-5933-bb80-e6d04ff878d7'::uuid),
