-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('6b7d34d4-2b87-58b3-a867-3e62064c2932'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Quelle suite modélise une augmentation de t % à chaque étape ?', 'mcq', '["Une suite géométrique de raison 1 + t/100","Une suite arithmétique de raison t","Une suite arithmético-géométrique","Une suite constante"]'::jsonb, 0, 'Deux hausses de 10 % donnent 21 %, et non 20 %.', 1),
    ('51fd7bd8-fdc1-5f9e-bc30-0869e4d88cf5'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Comment résout-on u(n+1) = a u(n) + b ?', 'mcq', '["On cherche le point fixe c, puis on pose v(n) = u(n) − c","On divise par b","On dérive la relation","On applique directement la formule géométrique"]'::jsonb, 0, 'La suite v obtenue est géométrique de raison a.', 2),
    ('3ea23b45-dce2-5825-955f-28114f5d5db0'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Que vaut le point fixe de u(n+1) = a u(n) + b, pour a ≠ 1 ?', 'mcq', '["b/(1 − a)","b/a","a/b","a + b"]'::jsonb, 0, 'C’est la solution de c = a c + b.', 3),
    ('2322f031-b3f8-57de-8b0b-56b11d52e8fc'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Vers quoi converge une suite arithmético-géométrique quand |a| < 1 ?', 'mcq', '["Vers le point fixe, quelle que soit la valeur initiale","Vers 0","Vers b","Elle diverge"]'::jsonb, 0, 'Le système s’installe dans un état d’équilibre.', 4),
    ('68fbc76f-65f2-5501-896c-c0e245bfa67d'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Quelle est la limite de qⁿ pour q > 1 ?', 'mcq', '["+∞","0","1","Elle n’existe pas"]'::jsonb, 0, 'Pour −1 < q < 1, la limite vaut 0.', 5),
    ('4f52391c-76ad-51c9-9ac6-89c09c40fe95'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Une suite croissante et majorée converge.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le théorème garantit l’existence de la limite, mais pas sa valeur.', 6),
    ('45f29c59-462a-585c-800e-165922979a47'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Quel outil permet de résoudre une question de seuil sur une suite géométrique ?', 'mcq', '["Le logarithme, ou un algorithme de seuil","La dérivée","Le théorème des gendarmes","Une intégrale"]'::jsonb, 0, 'L’algorithme est souvent la seule méthode possible sur un modèle complexe.', 7),
    ('4dc3a64f-0a37-5433-a8bc-eddaf180c4ff'::uuid, '91de43fd-05e7-50e4-884c-fcd320a29c78'::uuid, 'Une suite définie par récurrence permet de calculer directement n’importe quel terme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut passer par tous les précédents ; seule la forme explicite le permet.', 8),
    ('cf8a7fa0-e488-5eeb-b14c-5b2bb1384756'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Quelles sont les quatre formes indéterminées ?', 'mcq', '["∞ − ∞, 0 × ∞, ∞/∞ et 0/0","1/0 et 0/1","∞ + ∞ et 0 − 0","1^∞ uniquement"]'::jsonb, 0, 'Elles signalent qu’il faut transformer l’écriture.', 1),
    ('175eb1f0-b09b-5e86-bcb7-309cf42f10d4'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Que vaut la limite de e^x/x^n en +∞ ?', 'mcq', '["+∞","0","1","Elle dépend de n"]'::jsonb, 0, 'L’exponentielle l’emporte sur toute puissance, quel que soit le degré.', 2),
    ('34f039b0-977a-5690-9aa2-7289c44cb22f'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Que vaut la limite de ln(x)/x en +∞ ?', 'mcq', '["0","+∞","1","Elle n’existe pas"]'::jsonb, 0, 'La puissance l’emporte sur le logarithme.', 3),
    ('444b4869-511a-5c52-8d76-cabc339da7e9'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Comment interprète-t-on une asymptote horizontale dans un modèle ?', 'mcq', '["Comme un niveau de saturation ou de stabilisation","Comme une valeur interdite","Comme un maximum atteint","Comme une erreur de modèle"]'::jsonb, 0, 'La population plafonne, la température se stabilise.', 4),
    ('8d16c9e9-bb31-5ff8-84e2-657dac769ee8'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Quelle technique lève une indétermination du type ∞/∞ pour une fraction rationnelle ?', 'mcq', '["Factoriser par le terme de plus haut degré","Dériver numérateur et dénominateur","Appliquer le théorème des gendarmes","Passer au logarithme"]'::jsonb, 0, 'La limite est celle du quotient des termes dominants.', 5),
    ('5985f44c-6ba7-5c56-bf73-51ec2734eb2a'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Que marque une asymptote verticale d’équation x = a ?', 'mcq', '["Une valeur interdite du modèle","Un niveau de saturation","Un maximum du modèle","Un point d’inflexion"]'::jsonb, 0, 'La fonction y tend vers l’infini.', 6),
    ('92332fea-385f-5297-9820-9c7b46b5c8b0'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Une croissance exponentielle finit-elle toujours par dépasser une croissance polynomiale ?', 'mcq', '["Oui, quel que soit le degré du polynôme","Non, si le degré est supérieur à 10","Non, jamais","Seulement si la base est supérieure à 2"]'::jsonb, 0, 'Le décrochage arrive tard, puis très vite.', 7),
    ('d73c4d4a-d109-53a8-81ab-7ffe9f743d8e'::uuid, '4cbaeaa9-192a-5b0c-b543-af7f1c797c51'::uuid, 'Dans un exercice de modélisation, le calcul de la limite suffit à répondre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’interprétation en français est attendue, et vaut autant de points.', 8),
    ('27f859ae-250f-51f2-a838-df302ffd1a1f'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Quand une fonction est-elle continue en a ?', 'mcq', '["Quand sa limite en a existe et vaut f(a)","Quand elle est définie en a","Quand elle est croissante","Quand elle est dérivable ailleurs"]'::jsonb, 0, 'Intuitivement, la courbe se trace sans lever le crayon.', 1),
    ('0a566c7b-3cd6-517a-966f-dbe5704853a5'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Que garantit le théorème des valeurs intermédiaires ?', 'mcq', '["L’existence d’au moins une solution à f(x) = k","L’unicité de la solution","La valeur exacte de la solution","La dérivabilité de la fonction"]'::jsonb, 0, 'Une grandeur variant continûment prend toutes les valeurs intermédiaires.', 2),
    ('ce3b2080-0265-5d8e-90f0-4c061a8906fb'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Quelle hypothèse ajoute l’unicité de la solution ?', 'mcq', '["La stricte monotonie","La dérivabilité","La positivité","La convexité"]'::jsonb, 0, 'C’est elle qui permet de parler du « moment où » un seuil est atteint.', 3),
    ('644f29d9-1912-56aa-a627-9e1a8d2d50f0'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Une fonction dérivable est-elle continue ?', 'mcq', '["Oui, toujours","Non, jamais","Seulement si elle est croissante","Seulement sur un intervalle fermé"]'::jsonb, 0, 'La réciproque, elle, est fausse.', 4),
    ('ac18a938-fa27-5a92-acc4-e0fdd6d2bb52'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Un tarif postal par tranche de poids est modélisé par une fonction continue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il varie par paliers : les théorèmes de continuité ne s’y appliquent pas.', 5),
    ('3d375ffe-28d7-5da1-a128-ed2739f9a1ae'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Quelle méthode approche une solution en divisant l’intervalle en deux à chaque étape ?', 'mcq', '["La dichotomie","Le balayage","La récurrence","La dérivation"]'::jsonb, 0, 'Le balayage, lui, évalue de proche en proche avec un pas décroissant.', 6),
    ('7152625b-5182-571f-b924-f7bd0a00a223'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Combien d’éléments la rédaction attendue du théorème comporte-t-elle ?', 'mcq', '["Trois : continuité, stricte monotonie, encadrement de k","Un seul : la conclusion","Deux : continuité et calcul","Quatre"]'::jsonb, 0, 'Chacun des trois est noté séparément.', 7),
    ('17b811ca-375c-5cb8-8209-14ea5e548c98'::uuid, '681e292d-6a9a-5e3c-b19e-75705e3417ce'::uuid, 'Le théorème des valeurs intermédiaires fournit la valeur de la solution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en prouve l’existence ; la valeur s’obtient par balayage ou dichotomie.', 8),
    ('2069b671-7f25-5285-9f77-07ccf46d15df'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Sur quel ensemble la fonction ln est-elle définie ?', 'mcq', '["]0 ; +∞[","ℝ","[0 ; +∞[","ℝ privé de 0"]'::jsonb, 0, 'La condition d’existence est à vérifier avant tout calcul.', 1),
    ('3e2a3c14-b4a5-5895-9a88-d2248430701f'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Que vaut ln(ab) pour a et b strictement positifs ?', 'mcq', '["ln a + ln b","ln a × ln b","ln(a + b)","ln(a) / ln(b)"]'::jsonb, 0, 'Le logarithme transforme les produits en sommes.', 2),
    ('4c3a80a8-01ed-5982-b1f2-0f248fd89efd'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Comment résout-on 1,04^n ≥ 2 ?', 'mcq', '["En passant au logarithme : n ≥ ln(2)/ln(1,04)","En divisant par 1,04","En élevant au carré","Par dichotomie uniquement"]'::jsonb, 0, 'Le logarithme fait descendre l’exposant.', 3),
    ('856745cf-2b50-5665-a17d-ef2e86026434'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'On trouve n ≥ 17,7 pour une question de seuil. Quelle réponse donner ?', 'mcq', '["18 ans","17 ans","17,7 ans","18,7 ans"]'::jsonb, 0, 'L’arrondi se fait dans le sens qui respecte l’inégalité, jamais au plus proche.', 4),
    ('22e50fe1-4c6e-52cb-acae-3869913dcd75'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Quelle est la dérivée de ln(x) ?', 'mcq', '["1/x","ln(x)/x","x","e^x"]'::jsonb, 0, 'Strictement positive, elle prouve la croissance de ln sur ]0 ; +∞[.', 5),
    ('29c46be4-ba39-5e71-8b07-65e6ed1074cf'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Sur une échelle logarithmique, une augmentation d’une unité correspond à…', 'mcq', '["Une multiplication de la grandeur physique","Une addition d’une unité","Un doublement systématique","Aucune variation"]'::jsonb, 0, 'C’est le cas des décibels, du pH et de la magnitude d’un séisme.', 6),
    ('3a07bb26-e8aa-5610-84fc-09ae478848ee'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'Que signale un nuage de points aligné après passage au logarithme ?', 'mcq', '["Un modèle exponentiel","Un modèle linéaire","Un modèle sans tendance","Une erreur de mesure"]'::jsonb, 0, 'Le logarithme linéarise une suite géométrique.', 7),
    ('27d9a553-128f-5ad0-bd7d-db0443d8290c'::uuid, '5c585bdd-d8c0-5f1a-82ed-f156e991bdea'::uuid, 'ln(a + b) est-il égal à ln a + ln b ?', 'mcq', '["Non, cette égalité est fausse","Oui, toujours","Oui, si a et b sont positifs","Oui, si a = b"]'::jsonb, 0, 'C’est l’erreur la plus fréquente sur le logarithme.', 8),
    ('494c6994-bd0b-52d3-9adf-2eff22f1c091'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Quelle est la dérivée de e^u ?', 'mcq', '["u′ e^u","e^u","u e^u","e^(u′)"]'::jsonb, 0, 'Oublier u′ inverse le sens de variation dans un modèle de décroissance.', 1),
    ('5144bb39-9535-57c7-ab0f-32dd9f931a78'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Quelle est la dérivée de ln(u) pour u strictement positive ?', 'mcq', '["u′ / u","1 / u","u / u′","u′ ln(u)"]'::jsonb, 0, 'C’est l’une des deux formules composées du complément.', 2),
    ('2b05a68c-bc63-520a-a695-2974a4c481c7'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Quelle est la dérivée d’un produit u v ?', 'mcq', '["u′v + u v′","u′ v′","u′v − u v′","(u v)′ = u v"]'::jsonb, 0, 'La dérivée d’un produit n’est jamais le produit des dérivées.', 3),
    ('0ef86987-42aa-542e-a6c7-01f21849c0c7'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Une dérivée qui s’annule en un point y crée-t-elle toujours un extremum ?', 'mcq', '["Non, il faut un changement de signe","Oui, toujours","Oui, si la fonction est croissante avant","Oui, si le point est intérieur à l’intervalle"]'::jsonb, 0, 'Pour x³, la dérivée s’annule en 0 sans extremum.', 4),
    ('dade85e5-7b0a-5e6d-8517-4b944bb769fc'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Quelle est la dérivée de e^(−0,2x) ?', 'mcq', '["−0,2 e^(−0,2x)","e^(−0,2x)","0,2 e^(−0,2x)","−e^(−0,2x)"]'::jsonb, 0, 'Le facteur u′ vaut ici −0,2.', 5),
    ('3fc62e6f-7310-5480-9bdc-815ee14ae2ca'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Pourquoi préciser l’intervalle de validité dans un problème d’optimisation ?', 'mcq', '["Un optimum hors de cet intervalle n’a aucun sens concret","Pour simplifier le calcul de la dérivée","Pour éviter les valeurs négatives de la dérivée","Ce n’est pas nécessaire"]'::jsonb, 0, 'L’extremum est alors atteint au bord de l’intervalle.', 6),
    ('6f1d069b-076c-5031-96f2-ac7db16432b6'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Qu’appelle-t-on coût marginal ?', 'mcq', '["La dérivée du coût total, soit le coût approché de l’unité supplémentaire","Le coût moyen par unité","Le coût fixe","La différence entre recette et coût"]'::jsonb, 0, 'Le bénéfice est maximal là où le coût marginal égale la recette marginale.', 7),
    ('37f5ed09-caf3-554d-b03a-0d3cfa4b0cac'::uuid, '59b97c4b-a586-5dc4-b11e-93fe097e0287'::uuid, 'Quelle est l’équation de la tangente en a ?', 'mcq', '["y = f′(a)(x − a) + f(a)","y = f(a)(x − a) + f′(a)","y = f′(a) x + a","y = f(a) x + f′(a)"]'::jsonb, 0, 'Le coefficient directeur est le nombre dérivé en a.', 8),
    ('a939c220-5285-51d0-a23d-3648bd89114f'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Quelle condition sur f″ caractérise une fonction convexe ?', 'mcq', '["f″ positive","f″ négative","f″ nulle","f″ croissante"]'::jsonb, 0, 'De façon équivalente, f′ est croissante.', 1),
    ('5f62eec1-471e-57ea-a5bf-5f9ed1ef6062'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Que signifie f′ > 0 et f″ < 0 pour une grandeur ?', 'mcq', '["Elle augmente de moins en moins vite","Elle augmente de plus en plus vite","Elle diminue","Elle est constante"]'::jsonb, 0, 'C’est une croissance qui ralentit, souvent vers un plafond.', 2),
    ('7ae93d92-8425-5306-80e6-f0e2a2366635'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Que marque un point d’inflexion sur une courbe de croissance ?', 'mcq', '["Le moment où la vitesse de croissance est maximale","Le maximum de la grandeur","Le début de la décroissance","La fin du phénomène"]'::jsonb, 0, 'Sur une courbe épidémique, c’est le pic des nouveaux cas quotidiens.', 3),
    ('80e346a8-2d19-5411-8bbd-4f8c28c1f75b'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Une fonction convexe a sa courbe…', 'mcq', '["Au-dessus de ses tangentes et au-dessous de ses cordes","Au-dessous de ses tangentes","Confondue avec ses tangentes","Au-dessus de ses cordes"]'::jsonb, 0, 'Elle « tient l’eau ».', 4),
    ('02505c0c-9859-5fe2-a439-2dbca3258280'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'La fonction ln est concave sur ]0 ; +∞[.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa dérivée 1/x est décroissante.', 5),
    ('ed877cfe-d456-5ddf-b2c5-88f51f87d1e8'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Une courbe logistique en S est…', 'mcq', '["Convexe puis concave, avec un point d’inflexion entre les deux","Convexe partout","Concave partout","Sans point d’inflexion"]'::jsonb, 0, 'Démarrage lent, accélération, puis ralentissement vers le plafond.', 6),
    ('0dc8622a-61db-55af-9192-f4d7e8587e6f'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'L’annulation de f″ en un point suffit-elle à en faire un point d’inflexion ?', 'mcq', '["Non, il faut un changement de signe de f″","Oui, toujours","Oui, si f est croissante","Oui, si f″ est continue"]'::jsonb, 0, 'Pour x⁴, f″(0) = 0 sans changement de convexité.', 7),
    ('9ddb6a54-6b44-59cd-bc54-e1672f32fbfd'::uuid, '390d7448-43b1-5d07-9ea3-8f6e04c86cbc'::uuid, 'Une fonction décroissante peut-elle être convexe ?', 'mcq', '["Oui, variation et convexité sont indépendantes","Non, jamais","Oui, seulement si elle est positive","Oui, seulement sur un intervalle borné"]'::jsonb, 0, 'Elle baisse alors de moins en moins vite.', 8),
    ('ed844fb4-ffd9-59e9-8e96-577df9145b6e'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Qu’est-ce qu’une primitive F de f ?', 'mcq', '["Une fonction dérivable telle que F′ = f","La dérivée de f","La fonction réciproque de f","La limite de f"]'::jsonb, 0, 'Deux primitives d’une même fonction diffèrent d’une constante.', 1),
    ('48b4a68c-552d-5d44-a77f-6c48cf6738d2'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Quelles sont les solutions de y′ = a y ?', 'mcq', '["Les fonctions x ↦ C e^(a x)","Les fonctions x ↦ a x + C","Les fonctions x ↦ C ln(a x)","La seule fonction nulle"]'::jsonb, 0, 'C’est l’équation d’une évolution proportionnelle à la quantité présente.', 2),
    ('96e8707b-a129-58ee-a07f-54cb819c136f'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Que modélise l’équation y′ = a y avec a < 0 ?', 'mcq', '["Une décroissance exponentielle, comme une élimination de médicament","Une croissance exponentielle","Une évolution linéaire","Une oscillation"]'::jsonb, 0, 'Désintégration radioactive et refroidissement suivent le même modèle.', 3),
    ('ecfe7dd1-4ab6-5b57-8694-92ba0b665eff'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Vers quoi converge la solution de y′ = a y + b quand a < 0 ?', 'mcq', '["Vers −b/a, le niveau d’équilibre","Vers 0","Vers b","Elle diverge"]'::jsonb, 0, 'Indépendamment de l’état de départ : c’est le modèle du refroidissement.', 4),
    ('115b7d93-a8da-5648-a67d-717e986862fa'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Comment détermine-t-on la constante C ?', 'mcq', '["Par la condition initiale","Par la dérivée seconde","Elle vaut toujours 1","Par la limite en +∞"]'::jsonb, 0, 'Sans condition initiale, le modèle reste indéterminé.', 5),
    ('378d63af-6887-5f02-abfd-3d8d50d55908'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Quelle est une primitive de u′/u ?', 'mcq', '["ln|u|","1/u","u²/2","u′ ln(u)"]'::jsonb, 0, 'C’est la lecture inverse de la dérivée de ln(u).', 6),
    ('0da85158-1720-5ff2-9296-c53d2ea2a10c'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'De quelle suite l’équation y′ = a y + b est-elle la version continue ?', 'mcq', '["La suite arithmético-géométrique u(n+1) = a u(n) + b","La suite arithmétique","La suite géométrique pure","La suite constante"]'::jsonb, 0, 'Les deux décrivent un taux plus un apport fixe, et convergent vers un équilibre.', 7),
    ('cd006fb3-c917-517f-a92f-33d1fa80c9e0'::uuid, '43aac144-f6f5-5a4d-95e8-4d94b349f41d'::uuid, 'Quelle est la solution particulière constante de y′ = a y + b ?', 'mcq', '["y = −b/a","y = b/a","y = b","y = 0"]'::jsonb, 0, 'Elle vérifie 0 = a y + b.', 8),
    ('932bdd37-a73f-5396-89be-674fe74960bb'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Que vaut l’intégrale de a à b de f si F est une primitive de f ?', 'mcq', '["F(b) − F(a)","F(a) − F(b)","F(b − a)","F(b) × F(a)"]'::jsonb, 0, 'Le résultat ne dépend pas de la primitive choisie.', 1),
    ('0cccf84c-c775-5dd6-af17-db6496558c77'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Que représente l’intégrale d’une vitesse sur une durée ?', 'mcq', '["La distance parcourue","L’accélération","La vitesse moyenne","Le temps écoulé"]'::jsonb, 0, 'L’unité du résultat est le produit des unités des deux axes.', 2),
    ('1a2bc86e-19c2-524e-aa07-7a4f760c4875'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Comment calcule-t-on la valeur moyenne de f sur [a ; b] ?', 'mcq', '["En divisant l’intégrale par (b − a)","En prenant (f(a) + f(b))/2","En multipliant l’intégrale par (b − a)","En dérivant l’intégrale"]'::jsonb, 0, 'La moyenne des valeurs aux bornes ne convient que pour une fonction affine.', 3),
    ('6ad6c0ff-3af2-5910-9d6e-e93e1649957b'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Une intégrale peut-elle être négative ?', 'mcq', '["Oui, si la fonction est négative sur l’intervalle","Non, c’est une aire","Non, jamais","Oui, si les bornes sont positives"]'::jsonb, 0, 'C’est une aire algébrique.', 4),
    ('7a815692-c914-519e-a534-797f74169cb2'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Que dit la relation de Chasles ?', 'mcq', '["De a à b, plus de b à c, égale de a à c","L’intégrale d’un produit est le produit des intégrales","L’intégrale est toujours positive","La valeur moyenne est la demi-somme des bornes"]'::jsonb, 0, 'Elle permet de découper une période d’étude.', 5),
    ('ec262ae5-a6c7-5436-b473-84f5ce302617'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Que représente l’aire entre deux courbes dans un modèle ?', 'mcq', '["Un écart cumulé entre deux scénarios","La valeur moyenne des deux","Le point d’intersection","La différence des maximums"]'::jsonb, 0, 'Économie réalisée, surplus de production, écart de consommation.', 6),
    ('f0d5458d-9fce-5db3-b062-ac4f7a8964cd'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Quelle est l’unité d’une puissance en kW intégrée sur des heures ?', 'mcq', '["Le kWh, une énergie","Le kW","L’heure","Sans unité"]'::jsonb, 0, 'Vérifier l’unité est le meilleur contrôle d’un calcul d’intégrale.', 7),
    ('c62d8dc1-644c-501a-890c-338531861a17'::uuid, 'd3df5984-3798-5323-a4b8-5b215ecf6ace'::uuid, 'Que faire quand aucune primitive ne s’exprime simplement ?', 'mcq', '["Approcher l’intégrale par la méthode des rectangles ou des trapèzes","Conclure que l’intégrale n’existe pas","Dériver la fonction","Changer les bornes"]'::jsonb, 0, 'C’est ce que fait la calculatrice.', 8),
    ('ba1c3747-5825-5e56-b261-7295b62b4a6d'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Que vaut la somme des probabilités d’une loi de probabilité ?', 'mcq', '["1","0","Le nombre de valeurs","Elle est variable"]'::jsonb, 0, 'C’est la première vérification de tout tableau de loi.', 1),
    ('7dcd2a47-ec10-5692-ae3b-e5272bc1a477'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'L’espérance d’une variable aléatoire est-elle toujours une valeur possible ?', 'mcq', '["Non, l’espérance d’un dé vaut 3,5","Oui, toujours","Oui, si la loi est discrète","Oui, si la loi est binomiale"]'::jsonb, 0, 'C’est une moyenne pondérée, pas une issue.', 2),
    ('f76529a2-a6b0-5b90-bc33-77b3a76e6cff'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Qu’est-ce qu’un jeu équitable ?', 'mcq', '["Un jeu dont l’espérance de gain est nulle","Un jeu où toutes les issues sont équiprobables","Un jeu sans mise","Un jeu à deux issues"]'::jsonb, 0, 'Une espérance négative rend le jeu perdant à long terme.', 3),
    ('cb55d8c9-8ccf-51d0-b29d-5024e9cf66f4'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Que vaut V(aX + b) ?', 'mcq', '["a² V(X)","a V(X) + b","a V(X)","a² V(X) + b²"]'::jsonb, 0, 'Le coefficient est au carré et la constante disparaît.', 4),
    ('e6fc2a16-f1e4-5b2f-b8b2-d8f9e883bf1f'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Quelles conditions doivent être réunies pour appliquer la loi binomiale ?', 'mcq', '["Épreuves identiques, indépendantes, à deux issues","Épreuves équiprobables et nombreuses","Un tirage sans remise","Une population infinie"]'::jsonb, 0, 'Un tirage sans remise dans une petite population viole l’indépendance.', 5),
    ('1c6449b0-e3bd-50f2-8911-d0565203c466'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Que vaut l’espérance d’une loi binomiale B(n ; p) ?', 'mcq', '["n p","p","n p (1 − p)","n / p"]'::jsonb, 0, 'La variance vaut, elle, n p (1 − p).', 6),
    ('7e538b9b-29eb-5474-90a2-806f82e097a0'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'Comment calcule-t-on P(X ≥ k) ?', 'mcq', '["1 − P(X ≤ k−1)","1 − P(X ≤ k)","P(X ≤ k) − 1","P(X = k) × k"]'::jsonb, 0, 'Le passage par l’événement contraire est l’automatisme à acquérir.', 7),
    ('6a238c11-3268-58e7-a2df-3c5b67552d96'::uuid, 'cd955e9d-4fb3-539c-8c96-cdbce5f79792'::uuid, 'L’égalité V(X + Y) = V(X) + V(Y) est-elle toujours vraie ?', 'mcq', '["Non, seulement si X et Y sont indépendantes","Oui, toujours","Oui, comme pour l’espérance","Non, jamais"]'::jsonb, 0, 'L’espérance, elle, est additive sans condition.', 8),
    ('efd52a3b-988b-5b18-b029-fded571295ff'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Comment calcule-t-on P(a ≤ X ≤ b) pour une loi à densité ?', 'mcq', '["Par l’intégrale de la densité entre a et b","Par la somme des probabilités","Par f(b) − f(a)","Par la moyenne de f"]'::jsonb, 0, 'Une probabilité est une aire sous la courbe de densité.', 1),
    ('000bb591-d3df-5ceb-9ca4-f08e76d464a1'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Que vaut P(X = c) pour une variable continue ?', 'mcq', '["0","1","f(c)","Cela dépend de la loi"]'::jsonb, 0, 'Une valeur isolée a une probabilité nulle sans être impossible.', 2),
    ('f61ea9b0-8530-5aba-b16c-4db55c4fc279'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Quelle propriété caractérise la loi exponentielle ?', 'mcq', '["L’absence de mémoire","La symétrie autour de la moyenne","La densité constante","La périodicité"]'::jsonb, 0, 'Un composant déjà ancien a la même probabilité de tenir qu’un neuf.', 3),
    ('46a88c5f-989b-5a64-9fbe-c56eb40b598f'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Que vaut l’espérance d’une loi exponentielle de paramètre λ ?', 'mcq', '["1/λ","λ","λ²","2/λ"]'::jsonb, 0, 'Et P(X > t) = e^(−λt).', 4),
    ('aadc4a9a-ea4d-5c07-9bfd-605ef5c4cf04'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Quelle est la densité d’une loi uniforme sur [a ; b] ?', 'mcq', '["La constante 1/(b − a)","x/(b − a)","e^(−x)","1"]'::jsonb, 0, 'Toutes les portions de même longueur ont la même probabilité.', 5),
    ('ca054c0e-53dc-5d1f-9f85-fd83f7c9a5d8'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Quelle proportion des valeurs d’une loi normale se trouve dans [μ − 2σ ; μ + 2σ] ?', 'mcq', '["Environ 95 %","Environ 68 %","Environ 99,7 %","Environ 50 %"]'::jsonb, 0, 'Environ 68 % dans [μ − σ ; μ + σ], 99,7 % dans [μ − 3σ ; μ + 3σ].', 6),
    ('2ee0a19c-d7c1-5e3b-85cf-62e58ad90fb6'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'La loi exponentielle est-elle adaptée à la modélisation de l’usure d’un pneu ?', 'mcq', '["Non, son absence de mémoire l’interdit","Oui, c’est le modèle standard","Oui, si λ est grand","Oui, à condition de tronquer la loi"]'::jsonb, 0, 'Elle convient à ce qui tombe en panne au hasard, pas à ce qui s’use.', 7),
    ('0e5a2043-13e4-5c4f-8173-789d4de202c7'::uuid, '5337b3a5-4cac-5702-9589-eab9d6ac90ef'::uuid, 'Pour une loi à densité, P(X < b) et P(X ≤ b) diffèrent-elles ?', 'mcq', '["Non, elles sont égales","Oui, de f(b)","Oui, la seconde est plus grande","Cela dépend de la loi"]'::jsonb, 0, 'La probabilité d’une valeur isolée étant nulle.', 8),
    ('d72eed90-0d79-5d66-9f73-b4faeef9d168'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Par quel point la droite de régression passe-t-elle toujours ?', 'mcq', '["Le point moyen G","L’origine","Le premier point du nuage","Le point le plus élevé"]'::jsonb, 0, 'C’est une propriété caractéristique de la méthode des moindres carrés.', 1),
    ('e5521276-653e-5631-866e-3b32f96606e8'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Que minimise la méthode des moindres carrés ?', 'mcq', '["La somme des carrés des écarts verticaux entre les points et la droite","La somme des écarts","La distance au point le plus éloigné","La pente de la droite"]'::jsonb, 0, 'D’où le nom de la méthode.', 2),
    ('ff39a65e-1f40-50ad-8bb2-4629695d9586'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Entre quelles valeurs le coefficient de corrélation linéaire est-il compris ?', 'mcq', '["−1 et 1","0 et 1","0 et 100","−∞ et +∞"]'::jsonb, 0, 'Proche de ±1, les points sont presque alignés.', 3),
    ('850d9417-886e-59ed-8930-d9ed2e796e58'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Un coefficient de corrélation nul signifie-t-il qu’il n’y a aucune liaison ?', 'mcq', '["Non, il n’y a pas de liaison AFFINE","Oui, aucune liaison","Oui, les variables sont indépendantes","Non, il y a toujours une liaison"]'::jsonb, 0, 'Une relation parabolique parfaite peut donner r nul.', 4),
    ('ff47c4e0-d64a-56be-8495-41ebb7ccf922'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Quelle est la différence entre interpoler et extrapoler ?', 'mcq', '["Interpoler estime dans la plage observée, extrapoler au-delà","Interpoler est plus risqué","Extrapoler concerne les valeurs manquantes","Il n’y a aucune différence"]'::jsonb, 0, 'Toute extrapolation doit être assortie d’une réserve.', 5),
    ('00a99baf-dda2-5e44-b7fc-522ff1b3577c'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Une forte corrélation entre deux variables prouve-t-elle une causalité ?', 'mcq', '["Non, un facteur commun ou une coïncidence peuvent l’expliquer","Oui, si r dépasse 0,9","Oui, toujours","Oui, si l’échantillon est grand"]'::jsonb, 0, 'Seule une expérimentation contrôlée établit une causalité.', 6),
    ('5295e3a1-95c4-54d7-9127-45ceccba77d5'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'Quel changement de variable linéarise un modèle exponentiel ?', 'mcq', '["Poser z = ln(y)","Poser z = y²","Poser z = 1/y","Poser z = ln(x)"]'::jsonb, 0, 'Poser z = ln(x) convient, lui, à un modèle logarithmique.', 7),
    ('83459f58-26c1-5f9b-ae49-5a95ba4be4ba'::uuid, '75f32d94-3176-5b1f-81ac-1813abf75034'::uuid, 'La droite de régression de y en x est la même que celle de x en y.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le choix dépend de la variable qu’on cherche à prévoir.', 8),
    ('bc996de8-13a8-5e4f-ab25-a9f3ef04b5de'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Que vaut i² ?', 'mcq', '["−1","1","0","i"]'::jsonb, 0, 'C’est la définition même du nombre i, qui fonde tout le chapitre.', 1),
    ('4af1404f-fa8d-5220-9028-10d15abc66d0'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Dans z = a + ib, la partie imaginaire de z est…', 'mcq', '["b, un nombre réel","ib","i","a"]'::jsonb, 0, 'La partie imaginaire est un réel : c’est un piège de vocabulaire fréquent.', 2),
    ('83c067cf-baa8-5cc1-bc53-817e9efb08c5'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Que vaut z × z̄ pour z = a + ib ?', 'mcq', '["a² + b², un réel positif","a² − b²","a² + b² + 2iab","2a"]'::jsonb, 0, 'C’est aussi |z|², et c’est ce qui rend la division possible.', 3),
    ('9e478a66-7466-5d1e-8000-c8cb19eb14de'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Comment met-on un quotient de complexes sous forme algébrique ?', 'mcq', '["En multipliant numérateur et dénominateur par le conjugué du dénominateur","En divisant les parties réelles entre elles","En passant au module","En élevant au carré"]'::jsonb, 0, 'Le dénominateur devient alors réel.', 4),
    ('4baaa5af-0206-53aa-89aa-555e58ede112'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'z est réel si et seulement si…', 'mcq', '["z = z̄","z = −z̄","|z| = 1","Re(z) = 0"]'::jsonb, 0, 'z est imaginaire pur si et seulement si z = −z̄.', 5),
    ('7d39e679-c74d-5738-9f2c-8fd8c9f76603'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Le module vérifie-t-il |z + z′| = |z| + |z′| ?', 'mcq', '["Non, on a seulement l’inégalité triangulaire","Oui, toujours","Oui, si z et z′ sont réels positifs uniquement","Non, on a toujours l’égalité inverse"]'::jsonb, 0, 'Le module est multiplicatif, pas additif.', 6),
    ('ad76c0cc-439b-5963-a2d8-b81701ee96ee'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Peut-on comparer deux nombres complexes avec le signe < ?', 'mcq', '["Non, ℂ n’est pas ordonné ; on ne compare que les modules","Oui, comme dans ℝ","Oui, en comparant les parties réelles","Oui, en comparant les modules et les arguments"]'::jsonb, 0, 'C’est la faute la plus lourde d’une copie sur ce chapitre.', 7),
    ('5835aa7e-63d8-50dd-81a9-7f70646519d0'::uuid, 'a5644003-2d97-571b-9483-f929e7d14378'::uuid, 'Une égalité entre deux complexes équivaut à combien d’égalités réelles ?', 'mcq', '["Deux","Une","Trois","Aucune"]'::jsonb, 0, 'Parties réelles égales ET parties imaginaires égales.', 8),
    ('7215b360-b6e8-54fd-8da8-c9b6fb414f5f'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Que représente |z(B) − z(A)| ?', 'mcq', '["La distance AB","L’angle entre deux vecteurs","L’affixe du milieu de [AB]","L’aire du triangle"]'::jsonb, 0, 'Un module est toujours une distance dans le plan complexe.', 1),
    ('c8d5c91f-9627-5cdf-970c-057b68c266d2'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Le complexe 0 possède-t-il un argument ?', 'mcq', '["Non, aucun","Oui, il vaut 0","Oui, il vaut π","Oui, une infinité"]'::jsonb, 0, 'Son module est nul : aucune direction n’est définie.', 2),
    ('5a1a462a-3ecc-58d8-8a1e-89a17a18e07f'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Que vaut arg(z z′) ?', 'mcq', '["arg z + arg z′","arg z × arg z′","arg z − arg z′","arg(z) / arg(z′)"]'::jsonb, 0, 'Multiplier, c’est additionner les arguments.', 3),
    ('77cc836e-b6e3-5bae-b67f-39f2f1045fef'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Quelle est la forme trigonométrique d’un complexe non nul ?', 'mcq', '["r (cos θ + i sin θ) avec r = |z| et θ = arg z","a + ib","r + iθ","cos θ + i sin θ uniquement"]'::jsonb, 0, 'Le passage exige de résoudre les deux équations cos θ = a/r et sin θ = b/r.', 4),
    ('c64bbe69-c7c7-5901-a05e-a43185d830da'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Quel ensemble décrit l’équation |z − z(A)| = R ?', 'mcq', '["Le cercle de centre A et de rayon R","La médiatrice de [OA]","Une droite passant par A","Un disque plein"]'::jsonb, 0, '|z − z(A)| = |z − z(B)| décrit, elle, la médiatrice de [AB].', 5),
    ('82af04ef-1889-507d-a243-b1840a606f02'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Trois points A, B, C sont alignés si et seulement si…', 'mcq', '["Le quotient (z(C) − z(A))/(z(B) − z(A)) est réel","Ce quotient est imaginaire pur","Ce quotient a un module égal à 1","Ce quotient est nul"]'::jsonb, 0, 'S’il est imaginaire pur, les droites (AB) et (AC) sont perpendiculaires.', 6),
    ('a65e3ff1-bfa2-5592-b55f-2677e8003ee9'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'L’argument d’un complexe est défini modulo 2π.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un complexe non nul possède donc une infinité d’arguments.', 7),
    ('7d941300-8260-5aba-89e3-1a9a47a4f75f'::uuid, '29702f66-7568-50d8-a4ce-14c307c81c29'::uuid, 'Quelle est l’image du conjugué de z ?', 'mcq', '["Le symétrique de M par rapport à l’axe des abscisses","Le symétrique par rapport à l’origine","Le symétrique par rapport à l’axe des ordonnées","Le point M lui-même"]'::jsonb, 0, 'L’image de −z est, elle, le symétrique par rapport à l’origine.', 8),
    ('b6af7e5c-c105-5be2-a626-6640c48386c2'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Que vaut e^(iθ) ?', 'mcq', '["cos θ + i sin θ","cos θ − i sin θ","sin θ + i cos θ","e^θ (cos θ + i sin θ)"]'::jsonb, 0, 'C’est la définition de la notation exponentielle.', 1),
    ('de3280b0-5287-5900-9438-84e50260451f'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Que dit la formule de Moivre ?', 'mcq', '["(cos θ + i sin θ)ⁿ = cos(nθ) + i sin(nθ)","cos(nθ) = n cos θ","e^(iθ) = 1 + iθ","cos²θ + sin²θ = 1"]'::jsonb, 0, 'Élever à une puissance revient à multiplier l’argument par n.', 2),
    ('01310142-26ae-5f18-a073-e7e90b2df260'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Quelle est l’expression de cos θ par les formules d’Euler ?', 'mcq', '["(e^(iθ) + e^(−iθ))/2","(e^(iθ) − e^(−iθ))/2","(e^(iθ) − e^(−iθ))/(2i)","e^(iθ)/2"]'::jsonb, 0, 'Le sinus, lui, s’obtient avec la différence divisée par 2i.', 3),
    ('0b265512-e7b2-5871-b0d6-5f515000f3ed'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Que vaut e^(iπ) ?', 'mcq', '["−1","1","i","0"]'::jsonb, 0, 'D’où l’identité e^(iπ) + 1 = 0.', 4),
    ('6c487086-9d7f-52c7-83ae-e7a920ff0e67'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'À quoi servent les formules d’Euler ?', 'mcq', '["À linéariser des puissances de cosinus et de sinus","À calculer des modules","À résoudre des équations du second degré","À déterminer un argument"]'::jsonb, 0, 'La linéarisation est indispensable pour intégrer cos²θ ou sin³θ.', 5),
    ('7df66d7c-6f83-5c68-a739-59edf7a65962'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Quel est le conjugué de r e^(iθ) ?', 'mcq', '["r e^(−iθ)","−r e^(iθ)","(1/r) e^(iθ)","r e^(iθ)"]'::jsonb, 0, 'Conjuguer change le signe de l’argument, pas celui du module.', 6),
    ('9c8fbb40-88ea-5727-848e-e91aace5a3dc'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'Combien y a-t-il de racines n-ièmes de l’unité ?', 'mcq', '["n","Une seule","Deux","Une infinité"]'::jsonb, 0, 'Leurs images forment un polygone régulier à n côtés inscrit dans le cercle unité.', 7),
    ('ee0a4739-d90c-50d6-bbdc-41dcb7901ae7'::uuid, '1713e0c4-8a3e-5ec5-bdcd-1cc7f3984cf7'::uuid, 'La somme des racines n-ièmes de l’unité est nulle pour n ≥ 2.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une conséquence de leur répartition régulière sur le cercle.', 8),
    ('f5b41b89-3488-5f7c-8809-31b60a4cee9b'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Que donne une équation du second degré à coefficients réels avec Δ < 0 ?', 'mcq', '["Deux solutions complexes conjuguées","Aucune solution","Une solution double","Deux solutions réelles"]'::jsonb, 0, 'z = (−b ± i√(−Δ))/(2a).', 1),
    ('3f3bca43-9dfe-55c9-9f99-30053ab4e326'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Que dit le théorème fondamental de l’algèbre ?', 'mcq', '["Tout polynôme non constant admet au moins une racine dans ℂ","Tout polynôme a des racines réelles","Un polynôme de degré n a n racines réelles","Toute équation a une solution unique"]'::jsonb, 0, 'Un polynôme de degré n a donc exactement n racines comptées avec multiplicité.', 2),
    ('881b5eca-4099-5d08-aa5f-5e30a87de1b3'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Si un polynôme à coefficients réels admet la racine z, que peut-on dire ?', 'mcq', '["z̄ est aussi racine","z est nécessairement réel","−z est aussi racine","1/z est aussi racine"]'::jsonb, 0, 'Les racines non réelles vont par paires conjuguées.', 3),
    ('a3a30b34-711c-5efa-b0fa-3047ae9a6989'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Un polynôme de degré impair à coefficients réels admet…', 'mcq', '["Au moins une racine réelle","Aucune racine réelle","Uniquement des racines complexes","Exactement une racine"]'::jsonb, 0, 'Les racines non réelles allant par paires, il en reste au moins une réelle.', 4),
    ('ad9f2fe9-a365-51d2-840f-94f25c1832ee'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Combien l’équation zⁿ = a (a non nul) admet-elle de solutions ?', 'mcq', '["n","Une seule","Deux","Une infinité"]'::jsonb, 0, 'Leurs images forment un polygone régulier à n côtés.', 5),
    ('015d40c2-0cfa-54de-b791-46d6196fb62d'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Comment résout-on l’équation zⁿ = a ?', 'mcq', '["En passant à la forme exponentielle","En développant le binôme","En calculant le discriminant","En prenant la racine n-ième réelle"]'::jsonb, 0, 'On identifie module et argument, en n’oubliant pas le 2kπ.', 6),
    ('6eef993b-95d5-5c2f-aecb-7eb3983c4e0e'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Peut-on écrire √(−4) = 2i ?', 'mcq', '["Non, le symbole racine n’est pas défini sur les négatifs","Oui, c’est la notation usuelle","Oui, si l’on précise le signe","Oui, mais seulement pour −1"]'::jsonb, 0, 'Il faut écrire i√4, ou i × 2.', 7),
    ('6c873678-c6c5-54c6-a5ec-7a119e39ca92'::uuid, 'c1ef7301-9597-5e31-9343-39e0b8e2f186'::uuid, 'Que valent la somme et le produit des racines de a z² + b z + c ?', 'mcq', '["S = −b/a et P = c/a","S = b/a et P = −c/a","S = −c/a et P = b/a","S = a/b et P = a/c"]'::jsonb, 0, 'Elles permettent de retrouver la seconde racine quand la première est connue.', 8),
    ('3474e254-70e7-58a7-b2f5-6de682535fdf'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Quelle transformation l’écriture z′ − ω = e^(iθ)(z − ω) décrit-elle ?', 'mcq', '["La rotation de centre Ω et d’angle θ","L’homothétie de centre Ω","La translation de vecteur ω","La symétrie par rapport à Ω"]'::jsonb, 0, 'Une rotation est une multiplication par un complexe de module 1.', 1),
    ('b7491c2b-2aa7-5454-a855-e404e60cc673'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Que produit la multiplication par i ?', 'mcq', '["Une rotation d’angle +π/2 autour de l’origine","Une symétrie par rapport à l’origine","Une homothétie de rapport 2","Une translation"]'::jsonb, 0, 'C’est l’intuition la plus utile du chapitre.', 2),
    ('319faa8f-dad5-5717-946e-5d6c467a17cd'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Que représente |(z(C) − z(A))/(z(B) − z(A))| ?', 'mcq', '["Le rapport AC/AB","L’angle en A","L’aire du triangle ABC","La distance BC"]'::jsonb, 0, 'L’argument du même quotient donne, lui, l’angle.', 3),
    ('40a125d8-5987-539e-9a7f-491027843bc9'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Quelle condition caractérise un triangle isocèle en A ?', 'mcq', '["Le module du quotient vaut 1","Le quotient est réel","Le quotient est imaginaire pur","Le quotient est nul"]'::jsonb, 0, 'AB = AC se lit directement sur le module.', 4),
    ('a1840a49-12eb-5404-960d-e7e8ca261119'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Quelle transformation z′ = z + b décrit-elle ?', 'mcq', '["La translation de vecteur d’affixe b","L’homothétie de rapport b","La rotation d’angle b","La similitude de rapport b"]'::jsonb, 0, 'C’est la plus simple des écritures complexes de transformation.', 5),
    ('791ac52f-9c79-5903-b89d-cbea2003b5f8'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Toute application z ↦ a z + b avec a non nul est une similitude directe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le module de a donne le rapport, son argument donne l’angle.', 6),
    ('11b24301-aa9a-5508-9e7a-68a11e856318'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Quel ensemble décrit arg(z − a) = θ modulo 2π ?', 'mcq', '["Une demi-droite d’origine le point d’affixe a","Un cercle de centre a","Une droite passant par a","Le point a lui-même"]'::jsonb, 0, 'L’origine elle-même en est exclue, l’argument de 0 n’existant pas.', 7),
    ('b573504c-f00c-5c7a-81d4-f7695c1c8fde'::uuid, 'dcf87163-bbc4-5e5a-b7df-26bfed2f4eee'::uuid, 'Les nombres complexes permettent-ils de traiter la géométrie de l’espace ?', 'mcq', '["Non, ils ne décrivent que le plan","Oui, avec trois coordonnées","Oui, par le produit scalaire complexe","Oui, à partir de la forme exponentielle"]'::jsonb, 0, 'L’espace relève du produit scalaire et des coordonnées.', 8),
    ('6e5320d0-9ab7-5f7c-974a-a09b96f92829'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Que signifie a ≡ b [n] ?', 'mcq', '["n divise a − b, autrement dit a et b ont le même reste modulo n","a est égal à b","a divise b et n","n divise a et b"]'::jsonb, 0, 'C’est la définition de la congruence modulo n.', 1),
    ('f85e8551-fac2-541e-b19f-9e8e9f679d3b'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Quelle condition assure l’unicité du couple (q ; r) dans la division euclidienne ?', 'mcq', '["0 ≤ r < b","r ≤ b","r > 0","q > 0"]'::jsonb, 0, 'L’oublier conduit à des restes négatifs, notamment pour a négatif.', 2),
    ('fa78503d-53f6-5850-ac00-7e58ca5f1a53'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Quel est le reste de la division euclidienne de −7 par 3 ?', 'mcq', '["2","−1","1","−7"]'::jsonb, 0, 'On a −7 = 3 × (−3) + 2, avec 0 ≤ 2 < 3.', 3),
    ('426c5dd3-9e63-571f-9ab1-a58cbb386d87'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Les congruences sont-elles compatibles avec la division ?', 'mcq', '["Non, simplifier exige des précautions liées au PGCD","Oui, comme avec la multiplication","Oui, si le diviseur est premier avec n","Oui, toujours"]'::jsonb, 0, 'De 6 ≡ 12 [6] on ne peut pas déduire 3 ≡ 6 [6].', 4),
    ('f37866ba-2134-574a-b738-ed3233eb3920'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Si b divise a et a′, que divise-t-il aussi ?', 'mcq', '["Toute combinaison linéaire u a + v a′","Le produit a a′ uniquement","La somme a + a′ uniquement","Rien d’autre"]'::jsonb, 0, 'C’est la propriété la plus utilisée en démonstration.', 5),
    ('cf763289-90e8-54ac-ba2d-85f2c4926587'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Comment détermine-t-on le reste d’une grande puissance modulo n ?', 'mcq', '["En cherchant la périodicité des puissances successives","En calculant la puissance entière","En divisant l’exposant par n","En passant au logarithme"]'::jsonb, 0, 'Le cycle des restes permet de ramener l’exposant à son reste modulo la période.', 6),
    ('47bc7c95-245c-5277-8a43-d94cc9ea2457'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Pourquoi un nombre est-il congru à la somme de ses chiffres modulo 9 ?', 'mcq', '["Parce que 10 ≡ 1 [9]","Parce que 9 est impair","Parce que 10 ≡ −1 [9]","C’est une coïncidence"]'::jsonb, 0, 'Le critère de divisibilité par 11 vient, lui, de 10 ≡ −1 [11].', 7),
    ('1107e4fc-cc62-560c-bf29-b1b663cf2c7b'::uuid, '9f5672d9-759b-5549-8aeb-313f77e9db83'::uuid, 'Tout entier divise 0.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '0 = b × 0 pour tout entier b.', 8),
    ('b3a4e781-5dd3-5596-8eeb-68475d199d06'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Que dit le théorème de Bézout ?', 'mcq', '["a et b sont premiers entre eux si et seulement s’il existe u, v tels que a u + b v = 1","Le PGCD divise toujours la somme","a divise b c implique a divise c","Tout entier est produit de nombres premiers"]'::jsonb, 0, 'Exhiber un seul couple (u ; v) suffit à prouver la primalité relative.', 1),
    ('6cd678cf-10e6-5f5f-a91f-66c9b11210dc'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Que dit le théorème de Gauss ?', 'mcq', '["Si a divise b c et a est premier avec b, alors a divise c","Si a divise b c, alors a divise c","Le PGCD de a et b divise a + b","Tout nombre premier divise un produit"]'::jsonb, 0, 'L’hypothèse de primalité est indispensable : 6 divise 4 × 3 sans diviser 4 ni 3.', 2),
    ('5857045a-2c28-5d61-859e-4823002b8f3e'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Sur quelle égalité repose l’algorithme d’Euclide ?', 'mcq', '["PGCD(a ; b) = PGCD(b ; r), r étant le reste de a par b","PGCD(a ; b) = a − b","PGCD(a ; b) × PPCM(a ; b) = a + b","PGCD(a ; b) = b"]'::jsonb, 0, 'Le dernier reste non nul est le PGCD.', 3),
    ('8772c347-e737-5450-9d71-3dc7362cfaa0'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, '« Premiers entre eux » signifie-t-il que les deux nombres sont premiers ?', 'mcq', '["Non, cela signifie que leur PGCD vaut 1","Oui, toujours","Oui, si les deux sont impairs","Non, cela signifie qu’ils sont consécutifs"]'::jsonb, 0, '8 et 9 sont premiers entre eux sans qu’aucun soit premier.', 4),
    ('a42799ff-f967-5660-9c80-ef7c42de0b14'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Quand l’équation a x + b y = c admet-elle des solutions entières ?', 'mcq', '["Si et seulement si PGCD(a ; b) divise c","Toujours","Si a et b sont premiers","Si c est positif"]'::jsonb, 0, 'C’est la première vérification de tout exercice d’équation diophantienne.', 5),
    ('63356e69-e997-5b56-9851-52a3e68f3f1f'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Comment obtient-on les coefficients de Bézout ?', 'mcq', '["En remontant l’algorithme d’Euclide","Par tâtonnement uniquement","Par la décomposition en facteurs premiers","Ils valent toujours 1 et −1"]'::jsonb, 0, 'On exprime chaque reste en fonction des précédents, de proche en proche.', 6),
    ('4c613c1e-b325-5610-970d-e791ce7e06ec'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Quelle relation lie PGCD et PPCM de deux entiers ?', 'mcq', '["Leur produit vaut |a b|","Leur somme vaut a + b","Le PPCM divise le PGCD","Ils sont toujours égaux"]'::jsonb, 0, 'Connaître l’un donne donc immédiatement l’autre.', 7),
    ('49785a53-be89-54ed-828a-885837f0062e'::uuid, 'bcacdfed-4f28-53cb-8ec2-c5c226f82a4e'::uuid, 'Si b et c divisent a et sont premiers entre eux, leur produit divise a.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un corollaire direct du théorème de Gauss.', 8),
    ('172782c4-6e94-5939-ad21-c30d594bdd6d'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Pourquoi 1 n’est-il pas un nombre premier ?', 'mcq', '["Il n’a qu’un seul diviseur positif, et son exclusion assure l’unicité de la décomposition","Parce qu’il est trop petit","Parce qu’il est impair","C’est une convention sans justification"]'::jsonb, 0, 'Sans cette exclusion, toute décomposition admettrait une infinité d’écritures.', 1),
    ('8dced2db-ad85-528a-a6f2-f63c44f3da42'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Que dit le petit théorème de Fermat ?', 'mcq', '["Si p est premier et a non divisible par p, alors a^(p−1) ≡ 1 [p]","Tout entier est somme de deux nombres premiers","a^p ≡ p [a]","Il n’existe pas de solution à xⁿ + yⁿ = zⁿ"]'::jsonb, 0, 'Sa forme générale, a^p ≡ a [p], vaut pour tout entier a.', 2),
    ('b77c2012-bdf3-5755-8de1-bcad13c2a43b'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Jusqu’à quelle valeur faut-il tester les diviseurs pour savoir si n est premier ?', 'mcq', '["Jusqu’à √n","Jusqu’à n/2","Jusqu’à n − 1","Jusqu’à n"]'::jsonb, 0, 'Un entier composé a nécessairement un diviseur inférieur ou égal à √n.', 3),
    ('fa0a97f2-3872-54ee-9200-9a602a954341'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Que dit le théorème fondamental de l’arithmétique ?', 'mcq', '["Tout entier supérieur ou égal à 2 se décompose de façon unique en produit de facteurs premiers","Il existe une infinité de nombres premiers","Tout entier premier est impair","Le PGCD divise le PPCM"]'::jsonb, 0, 'L’unicité s’entend à l’ordre des facteurs près.', 4),
    ('9996cce5-8daa-5c45-b7f0-d2bb50f2e927'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Comment Euclide démontre-t-il l’infinité des nombres premiers ?', 'mcq', '["Par l’absurde, en considérant le produit de tous plus 1","Par récurrence","Par le crible d’Ératosthène","Par le petit théorème de Fermat"]'::jsonb, 0, 'Ce nouvel entier n’est divisible par aucun des premiers supposés.', 5),
    ('f717a03f-a5c3-568f-a89e-de11e3215755'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Le petit théorème de Fermat reste-t-il vrai pour un modulo composé ?', 'mcq', '["Non, l’hypothèse « p premier » est indispensable","Oui, toujours","Oui, si a est premier","Oui, pour les modulos pairs"]'::jsonb, 0, 'C’est ce qui rend les tests de primalité seulement probabilistes.', 6),
    ('7a31c877-4b4f-5b31-8450-20129ba68ffa'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, 'Sur quoi repose la sécurité du chiffrement RSA ?', 'mcq', '["Sur la difficulté de factoriser le produit de deux grands nombres premiers","Sur la difficulté de multiplier deux grands nombres","Sur la longueur des clés uniquement","Sur le crible d’Ératosthène"]'::jsonb, 0, 'Multiplier est immédiat, factoriser ne l’est pas : c’est l’asymétrie exploitée.', 7),
    ('44eb6e8d-4781-506e-8cbf-3d9efae5bc7d'::uuid, '44339491-b4cf-5db0-9e02-e1a7b4cda5bc'::uuid, '2 est le seul nombre premier pair.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tout autre nombre pair admet 2 comme diviseur propre.', 8),
    ('b8b05674-10b0-5d06-af32-a3733cce7a06'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Quand le produit A × B est-il défini ?', 'mcq', '["Quand le nombre de colonnes de A égale le nombre de lignes de B","Quand A et B ont la même taille","Quand A et B sont carrées","Toujours"]'::jsonb, 0, 'Si A est n × p et B est p × q, le produit est n × q.', 1),
    ('1206a49d-c205-590c-9f64-c42e0b58f60e'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Le produit matriciel est-il commutatif ?', 'mcq', '["Non, A B et B A diffèrent en général","Oui, toujours","Oui, pour les matrices carrées","Oui, si les matrices sont inversibles"]'::jsonb, 0, 'L’un peut même exister sans l’autre.', 2),
    ('630721d2-a358-556c-9343-500e082c9353'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Quand une matrice 2 × 2 est-elle inversible ?', 'mcq', '["Quand son déterminant ad − bc est non nul","Toujours","Quand tous ses coefficients sont non nuls","Quand elle est symétrique"]'::jsonb, 0, 'L’inverse s’obtient alors en divisant par ce déterminant.', 3),
    ('020dd78e-6379-5b3e-ba20-433db6844329'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Quel rôle joue la matrice identité ?', 'mcq', '["Celui du nombre 1 : A I = I A = A","Celui du nombre 0","Elle annule tout produit","Elle transpose la matrice"]'::jsonb, 0, 'Elle porte des 1 sur la diagonale et des 0 ailleurs.', 4),
    ('ad262bee-e3de-52e0-ab8f-3fd5c48ce1d5'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Comment calcule-t-on Aⁿ quand A = P D P⁻¹ avec D diagonale ?', 'mcq', '["Aⁿ = P Dⁿ P⁻¹","Aⁿ = Pⁿ D Pⁿ","Aⁿ = P D P⁻¹ ⁿ fois développé terme à terme","Aⁿ = Dⁿ"]'::jsonb, 0, 'Dⁿ s’obtient en élevant chaque coefficient diagonal à la puissance n.', 5),
    ('b745dcb6-cb83-52b8-882d-f164b1d4bbdd'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Un produit de deux matrices peut-il être nul sans qu’aucune ne le soit ?', 'mcq', '["Oui","Non, jamais","Oui, seulement pour les matrices 2 × 2","Oui, si l’une est l’identité"]'::jsonb, 0, 'C’est une autre différence majeure avec le calcul sur les réels.', 6),
    ('8c22e255-052e-59fe-8390-40be995ccbca'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Comment s’écrit un système linéaire sous forme matricielle ?', 'mcq', '["A X = B, X étant la colonne des inconnues","X A = B","A + X = B","A X B = 0"]'::jsonb, 0, 'Si A est inversible, la solution unique est X = A⁻¹ B.', 7),
    ('8873e4d4-0121-5433-8dac-33817420e346'::uuid, 'd1838198-042e-521e-a770-b2d493972663'::uuid, 'Toutes les matrices carrées sont inversibles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut que leur déterminant soit non nul.', 8),
    ('6b12c461-c9d5-5021-ac47-a3def0647b6f'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Que représente le coefficient (i ; j) de Mᵏ, M étant la matrice d’adjacence ?', 'mcq', '["Le nombre de chemins de longueur exactement k de i vers j","La distance entre i et j","Le degré du sommet i","Le poids de l’arête entre i et j"]'::jsonb, 0, 'C’est le résultat central du chapitre.', 1),
    ('e6652361-3cb2-5e83-8af0-4af4749591e0'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Pour un graphe non orienté, la matrice d’adjacence est…', 'mcq', '["Symétrique","Diagonale","Inversible","Triangulaire"]'::jsonb, 0, 'La présence d’une arête entre i et j se lit dans les deux cases.', 2),
    ('40acdcda-ae35-56f3-a778-cffa7c0f34c6'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'À quelle condition un graphe connexe possède-t-il une chaîne eulérienne ?', 'mcq', '["Il compte 0 ou 2 sommets de degré impair","Tous ses sommets ont le même degré","Il a un nombre pair de sommets","Il est complet"]'::jsonb, 0, 'C’est le théorème d’Euler ; avec 0 sommet impair, il existe même un cycle eulérien.', 3),
    ('e2d22178-21aa-5076-8488-639995c9ebca'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Qu’est-ce qu’une chaîne hamiltonienne ?', 'mcq', '["Une chaîne passant par chaque sommet une fois et une seule","Une chaîne empruntant chaque arête une fois","La chaîne la plus courte entre deux sommets","Un cycle de longueur paire"]'::jsonb, 0, 'Aucun critère simple n’existe pour son existence.', 4),
    ('d21f39dd-03b6-5b23-a683-b0e1a4415ee8'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Comment compte-t-on les chemins de longueur au plus k ?', 'mcq', '["En additionnant M + M² + … + Mᵏ","En calculant Mᵏ seulement","En multipliant les puissances entre elles","En inversant M"]'::jsonb, 0, 'Cette somme sert aussi à tester la connexité du graphe.', 5),
    ('9b81aeb6-a8fa-50d7-b6ba-7ff6ce2ff57f'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Qu’est-ce que le nombre chromatique d’un graphe ?', 'mcq', '["Le plus petit nombre de couleurs colorant les sommets sans que deux voisins partagent une couleur","Le nombre d’arêtes","Le degré maximal","Le nombre de cycles"]'::jsonb, 0, 'Il est majoré par le degré maximal augmenté de 1.', 6),
    ('5d5ea790-a440-55be-a3d7-07e7c7eaedaa'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Un graphe est connexe si la somme I + M + … + Mⁿ⁻¹ n’a aucun coefficient nul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un coefficient nul signalerait deux sommets qu’aucun chemin ne relie.', 7),
    ('d6f4674f-c8f4-5dad-8de5-09355c5d4235'::uuid, '0adfca24-b720-55fc-b090-04f61bbe4f39'::uuid, 'Quel est le degré d’un sommet dans un graphe non orienté ?', 'mcq', '["Son nombre d’arêtes","Son numéro dans la matrice","La longueur du plus long chemin qui en part","Le nombre de sommets qu’il ne touche pas"]'::jsonb, 0, 'Il se lit sur la somme de la ligne correspondante de la matrice d’adjacence.', 8),
    ('c0f0814b-5e12-5ac3-bb09-f73aad6df607'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Comment s’écrit un système de deux suites récurrentes couplées ?', 'mcq', '["U(n+1) = A U(n), avec U(n) matrice colonne","U(n+1) = U(n) + A","A U(n+1) = U(n)","U(n) = A + n"]'::jsonb, 0, 'La matrice A contient les coefficients du système.', 1),
    ('105697d4-c634-5a67-8575-b6d31936d0f1'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Quelle est la forme explicite de U(n) ?', 'mcq', '["Aⁿ U(0)","A U(0)ⁿ","nA U(0)","A U(n−1) + U(0)"]'::jsonb, 0, 'Tout le problème se ramène au calcul de Aⁿ.', 2),
    ('89b5bc5e-da76-5cdc-bc4c-6c811f971d7f'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Comment traite-t-on le cas U(n+1) = A U(n) + B ?', 'mcq', '["On cherche l’état stable C, puis on pose V(n) = U(n) − C","On divise par B","On dérive la relation","On calcule directement Aⁿ B"]'::jsonb, 0, 'La suite V vérifie alors une relation sans terme constant.', 3),
    ('c9c683a2-573b-5def-8147-f8be35aef442'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Que vaut l’état stable C dans le cas affine ?', 'mcq', '["(I − A)⁻¹ B, lorsque I − A est inversible","A⁻¹ B","B − A","A B"]'::jsonb, 0, 'Il est solution de C = A C + B.', 4),
    ('6922e7ff-80a8-5ab3-a07b-53381e312efc'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Si Aⁿ tend vers la matrice nulle dans un modèle affine, vers quoi converge U(n) ?', 'mcq', '["Vers l’état stable C, quelle que soit la situation initiale","Vers U(0)","Vers la matrice nulle","Elle diverge"]'::jsonb, 0, 'La répartition finale ne dépend alors pas de la répartition de départ.', 5),
    ('03a58773-ffb5-5a43-9f18-5251915f883c'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'Comment calcule-t-on Aⁿ quand une diagonalisation est fournie ?', 'mcq', '["Aⁿ = P Dⁿ P⁻¹","Aⁿ = Pⁿ Dⁿ","Aⁿ = D P⁻¹","Aⁿ = P⁻¹ Dⁿ P"]'::jsonb, 0, 'Dⁿ s’obtient en élevant chaque coefficient diagonal à la puissance n.', 6),
    ('a1844309-2950-5bdb-9c70-a7e5f314e46a'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'La méthode du cas affine matriciel est-elle la même que pour une suite arithmético-géométrique réelle ?', 'mcq', '["Oui, seule la nature des objets change","Non, elle est entièrement différente","Oui, mais uniquement en dimension 2","Non, elle exige la diagonalisation"]'::jsonb, 0, 'Chercher l’état stable puis se ramener au cas homogène.', 7),
    ('df5b596b-3d7a-5250-85c3-5c2630c83466'::uuid, 'e847fc79-e8b5-5909-8b87-4c19f8e4bb44'::uuid, 'L’intérêt du calcul matriciel est de traiter aussi simplement le cas à trois états que le cas à deux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il factorise un raisonnement qu’on saurait mener suite par suite.', 8),
    ('89d30d88-9c88-537f-bf22-e7da0154b67c'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Que dit la propriété de Markov ?', 'mcq', '["L’avenir ne dépend que de l’état présent, pas de l’historique","Toutes les transitions sont équiprobables","Le système revient toujours à son état initial","Les probabilités changent à chaque étape"]'::jsonb, 0, 'On dit que le processus est sans mémoire.', 1),
    ('b8bedc35-e2be-54be-9cac-339108c926b7'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Que vaut la somme des coefficients d’une ligne de la matrice de transition ?', 'mcq', '["1","0","Le nombre d’états","Elle est variable"]'::jsonb, 0, 'Chaque ligne est une distribution de probabilité : la matrice est stochastique.', 2),
    ('766faf96-334c-5485-9d17-1e2d1ebc9a40'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Que représente le coefficient (i ; j) de Tⁿ ?', 'mcq', '["La probabilité d’être en j après n étapes en partant de i","Le nombre de chemins de i vers j","La distance entre i et j","La probabilité de rester en i"]'::jsonb, 0, 'C’est l’analogue probabiliste du comptage de chemins par les puissances de matrice.', 3),
    ('a2761820-780d-5d7b-8c2f-7ec4c35e2224'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Comment caractérise-t-on un état stable π ?', 'mcq', '["Par π × T = π, avec somme des composantes égale à 1","Par π = 0","Par T × π = 0","Par π = T"]'::jsonb, 0, 'La condition de somme est indispensable : sans elle, le système a une infinité de solutions.', 4),
    ('1177c025-6d8e-522f-81f4-595a4143aca3'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Quand la distribution converge-t-elle vers l’unique état stable ?', 'mcq', '["Quand une puissance de T n’a aucun coefficient nul","Toujours","Quand la matrice est symétrique","Quand il n’y a que deux états"]'::jsonb, 0, 'La limite est alors indépendante de la distribution initiale.', 5),
    ('59d272be-7513-5e9e-8956-a7f664d5c472'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'La limite d’une chaîne de Markov convergente dépend de la distribution initiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement ce que dit le résultat de convergence : elle oublie d’où elle vient.', 6),
    ('46a8171f-65cf-5a2c-882b-1b23fd8f80e9'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Quelle vérification permet de repérer une erreur de calcul de l’état stable ?', 'mcq', '["La somme des composantes de π doit valoir 1","π doit être positive strictement","π doit être égale à une ligne de T","π doit être nulle"]'::jsonb, 0, 'La seconde vérification est que chaque ligne de T somme bien à 1.', 7),
    ('0275bebd-5d61-559d-bcd9-3ea94101e995'::uuid, 'c0f3cc02-5595-5df2-ba6b-fea66de91745'::uuid, 'Sur quel principe repose le classement originel des pages web par Google ?', 'mcq', '["Une marche aléatoire d’un internaute, modélisée par une chaîne de Markov","Le nombre de mots-clés","La date de publication","Le nombre de visiteurs"]'::jsonb, 0, 'Le classement est la distribution stable de cette marche.', 8),
    ('0970d38c-9d81-50c1-b0a5-3deccbfbdcae'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Que vaut 0! par convention ?', 'mcq', '["1","0","Indéfini","n"]'::jsonb, 0, 'Cette convention rend cohérentes toutes les formules de dénombrement.', 1),
    ('4e32b2fe-5409-56c9-8f49-618f2c3caaff'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Combien y a-t-il de k-uplets d’un ensemble à n éléments ?', 'mcq', '["n^k","k^n","n!/(n−k)!","C(n,k)"]'::jsonb, 0, 'Liste ordonnée avec répétition : c’est le tirage avec remise.', 2),
    ('973127d3-3f56-53bd-acec-7a0e6b69c18a'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Quelle formule compte les tirages ordonnés sans remise de k éléments parmi n ?', 'mcq', '["n!/(n−k)!","n^k","C(n,k)","k!"]'::jsonb, 0, 'Ce sont les arrangements : 8 × 7 × 6 pour un podium parmi 8 coureurs.', 3),
    ('e7e8d985-2412-5f37-b180-5fa34d9d8d40'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Que vaut C(n,k) ?', 'mcq', '["n! / (k! (n−k)!)","n! / (n−k)!","n^k / k!","k! (n−k)!"]'::jsonb, 0, 'Le k! au dénominateur efface l’ordre des k éléments choisis.', 4),
    ('15d0eb10-fc61-5983-a99e-5dca70643114'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Que dit la relation de Pascal ?', 'mcq', '["C(n,k) = C(n−1,k−1) + C(n−1,k)","C(n,k) = C(n,n−k)","C(n,k) = n × C(n−1,k)","C(n,k) = C(n−1,k) × k"]'::jsonb, 0, 'Soit un élément donné est dans la partie, soit il n’y est pas.', 5),
    ('ab33cd8e-e024-5de8-b744-2d25b9ea607c'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'C(n,k) = C(n, n−k).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Choisir k éléments revient à en écarter n−k : c’est la relation de symétrie.', 6),
    ('37321266-8d20-5a6d-9a30-959484dbf84c'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Que vaut la somme de tous les C(n,k) pour k allant de 0 à n ?', 'mcq', '["2ⁿ","n!","n²","n"]'::jsonb, 0, 'C’est le nombre total de parties d’un ensemble à n éléments.', 7),
    ('3c8203ac-0a4d-5895-8840-85a3cd460661'::uuid, '6a431763-c71e-55fe-ba1c-09ed79058f9e'::uuid, 'Combien de mains de 5 cartes peut-on former dans un jeu de 32 ?', 'mcq', '["C(32,5)","32⁵","32!/27!","5!"]'::jsonb, 0, 'L’ordre des cartes en main ne compte pas : c’est une combinaison.', 8),
    ('720707db-3fd5-57ef-a071-07041f00d3b4'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Quand trois vecteurs de l’espace sont-ils coplanaires ?', 'mcq', '["Quand l’un est combinaison linéaire des deux autres","Quand ils sont deux à deux colinéaires","Quand ils ont la même norme","Quand leur somme est nulle"]'::jsonb, 0, 'Trois vecteurs non coplanaires forment une base de l’espace.', 1),
    ('a4f5fce7-d2b5-52a2-b4ee-fe1bae0eb793'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Comment caractérise-t-on un plan de l’espace ?', 'mcq', '["Par un point et deux vecteurs directeurs non colinéaires","Par un point et un vecteur directeur","Par deux points distincts","Par un vecteur normal seulement"]'::jsonb, 0, 'Trois points non alignés le déterminent aussi.', 2),
    ('02aae900-28e8-580c-a1dc-8ecff09be985'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Dans l’espace, deux droites qui ne se coupent pas sont nécessairement parallèles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles peuvent être non coplanaires : c’est la nouveauté par rapport au plan.', 3),
    ('4a15b1e2-52a5-5c94-8bf7-60fd36f6711b'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Un point M appartient à la droite passant par A de vecteur directeur u si…', 'mcq', '["AM est colinéaire à u","AM est orthogonal à u","AM et u sont coplanaires","AM a la même norme que u"]'::jsonb, 0, 'C’est la caractérisation vectorielle d’une droite.', 4),
    ('ffaef716-59ab-52f6-a096-180c55c766ea'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Dans quel type de repère la formule de la distance AB est-elle valable ?', 'mcq', '["Un repère orthonormé","Tout repère","Un repère orthogonal seulement","Un repère du plan"]'::jsonb, 0, 'Sans orthonormalité, la formule de la norme ne s’applique pas.', 5),
    ('08146561-c52d-59f2-b1bd-38d3c7f3e196'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Que dit le théorème du toit ?', 'mcq', '["Si deux plans sécants contiennent chacun une de deux droites parallèles, leur intersection leur est parallèle","Deux plans parallèles n’ont aucune intersection","Trois plans se coupent toujours en un point","Une droite parallèle à un plan lui est orthogonale"]'::jsonb, 0, 'C’est le théorème le plus utilisé pour construire une intersection.', 6),
    ('e1f2f809-e37b-5b51-a55b-acff5e9913b1'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Trois vecteurs non coplanaires forment une base de l’espace.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tout vecteur de l’espace se décompose alors de façon unique sur eux.', 7),
    ('23ae0457-0458-5c86-bce5-c474cef7a120'::uuid, '3d640995-262e-5f69-bbf4-61f6660a5fa1'::uuid, 'Si une droite est parallèle à une droite contenue dans un plan, elle est parallèle à ce plan.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le critère de parallélisme droite-plan.', 8),
    ('c73965f2-ba88-504a-8be8-bec59e14c254'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Combien de positions relatives deux droites de l’espace peuvent-elles avoir ?', 'mcq', '["Trois : sécantes, parallèles, ou non coplanaires","Deux : sécantes ou parallèles","Quatre","Une seule"]'::jsonb, 0, 'La non-coplanarité est le cas propre à l’espace.', 1),
    ('ee039b42-030a-558c-818e-7bac79f3650e'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Que peut être l’intersection de deux plans sécants ?', 'mcq', '["Une droite","Un point","Un plan","L’ensemble vide"]'::jsonb, 0, 'Deux plans distincts ne se coupent jamais en un seul point.', 2),
    ('feb2b98a-7179-5019-8324-58812d939502'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Quand une droite est-elle parallèle à un plan ?', 'mcq', '["Quand son vecteur directeur est orthogonal au vecteur normal du plan","Quand son vecteur directeur est colinéaire au vecteur normal","Quand elle coupe le plan en un point","Quand elle est incluse dans un plan parallèle"]'::jsonb, 0, 'Elle est incluse dans le plan si en plus un de ses points y appartient.', 3),
    ('da60bf41-5415-5af0-b450-31b0df4c55ad'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Deux plans dont les vecteurs normaux sont colinéaires sont…', 'mcq', '["Parallèles ou confondus","Sécants","Orthogonaux","Non coplanaires"]'::jsonb, 0, 'Le critère porte sur les normaux, pas sur les directeurs.', 4),
    ('90e0b4de-4a37-5732-82d2-7101681fc37e'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Si le système d’intersection de deux droites n’a pas de solution, elles sont parallèles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles peuvent aussi être non coplanaires : c’est l’erreur récurrente du chapitre.', 5),
    ('46407502-7d2e-5ba7-b964-d1ba61fea9e4'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Que signifie une identité vraie pour tout paramètre après substitution d’une droite dans un plan ?', 'mcq', '["La droite est incluse dans le plan","La droite est parallèle stricte au plan","La droite coupe le plan","Le système est mal posé"]'::jsonb, 0, 'Tous les points de la droite vérifient alors l’équation du plan.', 6),
    ('9b461f7f-900a-5e27-9110-031978f28a18'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Trois plans peuvent n’avoir aucun point commun tout en étant sécants deux à deux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la configuration en prisme : trois droites d’intersection parallèles distinctes.', 7),
    ('58faab73-7dd9-5829-a5be-62d537ec5627'::uuid, '3e32e17a-188a-5d15-aa91-b46baf69ec40'::uuid, 'Comment déterminer si deux droites sont parallèles ?', 'mcq', '["En testant la colinéarité de leurs vecteurs directeurs","En résolvant le système","En comparant leurs points","En calculant leur produit scalaire"]'::jsonb, 0, 'Elles sont confondues si en plus un point de l’une appartient à l’autre.', 8),
    ('f15821ac-f5af-5f1b-bf89-97c1e71b0d93'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Quelle est l’expression du produit scalaire en repère orthonormé ?', 'mcq', '["xx′ + yy′ + zz′","xx′ − yy′ + zz′","(x + x′)(y + y′)","xyz + x′y′z′"]'::jsonb, 0, 'C’est la somme des produits des coordonnées de même rang.', 1),
    ('d7a9c5ad-95e6-5566-a3a3-3fa338155a93'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Deux vecteurs non nuls sont orthogonaux si et seulement si…', 'mcq', '["Leur produit scalaire est nul","Leur produit scalaire vaut 1","Ils ont la même norme","Ils sont colinéaires"]'::jsonb, 0, 'C’est le critère le plus utilisé du chapitre.', 2),
    ('7eb09b3b-d909-5215-a59c-a266d4a02f63'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Dans l’équation ax + by + cz + d = 0, que représente le triplet (a ; b ; c) ?', 'mcq', '["Un vecteur normal au plan","Un vecteur directeur du plan","Les coordonnées d’un point du plan","Rien de particulier"]'::jsonb, 0, 'Lire un vecteur normal sur une équation de plan est donc immédiat.', 3),
    ('d7565fa3-9ad8-5ffc-a902-e38fc6a4a450'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Que vaut u · u ?', 'mcq', '["‖u‖²","‖u‖","0","2‖u‖"]'::jsonb, 0, 'C’est ce qui permet d’appliquer les identités remarquables aux vecteurs.', 4),
    ('95c8eff3-cdc5-5e2c-a445-d9b29c775106'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Qu’est-ce que le projeté orthogonal d’un point sur un plan ?', 'mcq', '["Le point du plan le plus proche du point donné","Le centre du plan","L’intersection du plan avec l’axe des abscisses","Un point quelconque du plan"]'::jsonb, 0, 'La distance au plan est la distance à ce projeté.', 5),
    ('690c627a-513e-57ca-9532-9eefd8038909'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Il suffit qu’un vecteur soit orthogonal à deux vecteurs directeurs non colinéaires d’un plan pour lui être normal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il est alors orthogonal à toute combinaison linéaire de ces deux vecteurs.', 6),
    ('783b64a7-ed2d-5911-8a28-7f834a7d8e52'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Quelle expression relie produit scalaire, normes et angle ?', 'mcq', '["u · v = ‖u‖ ‖v‖ cos(θ)","u · v = ‖u‖ ‖v‖ sin(θ)","u · v = ‖u‖ + ‖v‖","u · v = ‖u‖ / ‖v‖"]'::jsonb, 0, 'Elle permet de calculer un angle à partir des coordonnées.', 7),
    ('c096a238-adbc-5361-91cc-2f6286a09e1f'::uuid, '57956afa-ee0e-581c-9a5a-2f87ecbbd000'::uuid, 'Comment détermine-t-on la position relative d’une sphère et d’un plan ?', 'mcq', '["En comparant la distance du centre au plan et le rayon","En calculant le produit scalaire des normaux","En résolvant un système de trois équations","En projetant le centre sur une droite"]'::jsonb, 0, 'Distance inférieure au rayon : intersection selon un cercle.', 8),
    ('75566d48-b4a8-5f89-8617-4f0a7e3c10e0'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Dans une représentation paramétrique de droite, que représentent les coefficients du paramètre t ?', 'mcq', '["Les coordonnées d’un vecteur directeur","Les coordonnées d’un point de la droite","Un vecteur normal","La distance à l’origine"]'::jsonb, 0, 'Les termes constants donnent, eux, un point de la droite.', 1),
    ('a6be957a-7af2-5f03-977d-6f4941ba59c7'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Une représentation paramétrique d’une droite est unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Changer de point de base ou de multiple du directeur donne une autre écriture de la même droite.', 2),
    ('69611755-26d9-56de-8c65-019765e9e062'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Comment obtient-on l’intersection d’une droite et d’un plan ?', 'mcq', '["En substituant la paramétrique dans l’équation cartésienne","En résolvant deux équations cartésiennes","En calculant un produit scalaire","En comparant les vecteurs normaux"]'::jsonb, 0, 'On obtient une équation du premier degré en t.', 3),
    ('80a565d4-81b4-5977-a172-b6a9004cc883'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Après substitution, on obtient une égalité du type 0 = 5. Que conclure ?', 'mcq', '["La droite est strictement parallèle au plan","La droite est incluse dans le plan","La droite coupe le plan en un point","Le calcul est faux"]'::jsonb, 0, 'Une identité 0 = 0 signifierait au contraire que la droite est incluse.', 4),
    ('6dab65ae-78ee-54ee-b397-41747882a6db'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Comment détermine-t-on le coefficient d dans ax + by + cz + d = 0 ?', 'mcq', '["En injectant les coordonnées d’un point connu du plan","En calculant la norme du vecteur normal","En posant d = 0","En résolvant un système de trois équations"]'::jsonb, 0, 'Les coefficients a, b, c viennent, eux, du vecteur normal.', 5),
    ('326263cd-e00b-52d7-b068-9bcae63fe868'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Comment obtenir une paramétrique de la droite d’intersection de deux plans ?', 'mcq', '["En résolvant le système, deux inconnues exprimées en fonction de la troisième prise comme paramètre","En additionnant les deux équations","En multipliant les vecteurs normaux","C’est impossible"]'::jsonb, 0, 'La troisième inconnue joue le rôle du paramètre t.', 6),
    ('b8ebce55-56f9-50d3-a470-3775e6d0b4e1'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Tester si un point appartient à un plan est immédiat avec une équation cartésienne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il suffit de remplacer et de vérifier l’égalité ; en paramétrique il faudrait résoudre un système.', 7),
    ('9574582d-971e-5f23-96b5-9de40d6dcd3f'::uuid, '82601e61-2358-5424-84e9-965689a8009e'::uuid, 'Combien d’équations cartésiennes faut-il pour décrire une droite de l’espace ?', 'mcq', '["Deux","Une","Trois","Aucune, seule la paramétrique convient"]'::jsonb, 0, 'Une droite de l’espace est l’intersection de deux plans.', 8),
    ('96ad3987-8bb8-5195-b0ac-d73cecf720b6'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Quelles sont les deux étapes d’un raisonnement par récurrence ?', 'mcq', '["L’initialisation et l’hérédité","L’hypothèse et la conclusion","La majoration et la minoration","Le calcul et la vérification"]'::jsonb, 0, 'La conclusion vient ensuite, mais elle ne se démontre pas.', 1),
    ('4ab3b865-1516-5319-ad6e-7998a06aca9e'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Que suppose-t-on dans l’étape d’hérédité ?', 'mcq', '["Que P(n) est vraie pour un entier n fixé","Que P(n+1) est vraie","Que P(n) est vraie pour tout n","Rien du tout"]'::jsonb, 0, 'Supposer P(n+1) reviendrait à supposer ce qu’on veut démontrer.', 2),
    ('7a70937d-349f-5391-9902-e6d9ef484c5b'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Une propriété héréditaire est-elle nécessairement vraie ?', 'mcq', '["Non, sans initialisation vraie elle ne prouve rien","Oui, l’hérédité suffit","Oui, si elle porte sur des entiers","Cela dépend de la propriété"]'::jsonb, 0, 'C’est l’échelle sans premier barreau.', 3),
    ('4d93ff95-1b34-5b48-a52e-a1077f55de4c'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Que dit l’inégalité de Bernoulli ?', 'mcq', '["(1 + a)ⁿ ≥ 1 + n a pour a > −1","(1 + a)ⁿ ≤ 1 + n a","aⁿ ≥ n a","(1 + a)ⁿ = 1 + n a"]'::jsonb, 0, 'Elle se démontre par récurrence sur n.', 4),
    ('b4e999d1-93fb-55cd-93fe-95cc0ee69e17'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Que signale une démonstration d’hérédité qui n’utilise jamais l’hypothèse de récurrence ?', 'mcq', '["Une erreur, ou une propriété démontrable directement","Une démonstration particulièrement élégante","Une propriété fausse","Une initialisation manquante"]'::jsonb, 0, 'L’hypothèse doit servir : c’est elle qui relie les deux rangs.', 5),
    ('b580c78d-9671-5b47-809c-d9e75c99438c'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'La récurrence peut servir à démontrer une propriété de divisibilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme les formules explicites, les inégalités ou la monotonie d’une suite.', 6),
    ('5c7e5870-8f51-5b2c-a9b4-fc221845dfe7'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'Dans l’hérédité, par quoi commence-t-on la démonstration ?', 'mcq', '["Par l’expression de rang n+1, où l’on fait apparaître celle de rang n","Par la conclusion","Par l’initialisation","Par le calcul de la limite"]'::jsonb, 0, 'C’est ce qui permet d’appliquer l’hypothèse de récurrence.', 7),
    ('ce147328-d2b3-5c23-ba93-2ad1fb44bf8e'::uuid, 'a741690e-ca12-53f0-bb61-d4352446bd62'::uuid, 'À quoi sert la récurrence dans l’étude des suites ?', 'mcq', '["À établir la monotonie et un encadrement, donc la convergence par le théorème de la limite monotone","À calculer directement la limite","À déterminer le premier terme","À vérifier la périodicité"]'::jsonb, 0, 'Croissante et majorée : la suite converge.', 8),
    ('a958615f-bb77-5537-8835-86c82e23e25c'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Une suite qui diverge tend-elle nécessairement vers l’infini ?', 'mcq', '["Non, elle peut n’avoir aucune limite","Oui, toujours","Oui, vers +∞ uniquement","Non, elle converge alors vers 0"]'::jsonb, 0, '(−1)ⁿ oscille entre −1 et 1 sans se fixer.', 1),
    ('0b2979ba-0d57-5075-a017-3eb77b617d09'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Quelle est la limite de qⁿ pour −1 < q < 1 ?', 'mcq', '["0","+∞","1","Elle n’existe pas"]'::jsonb, 0, 'Pour q > 1 la suite tend vers +∞, pour q ≤ −1 elle n’a pas de limite.', 2),
    ('28217cb8-cf40-505b-a213-c8edb333a92f'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Quelles sont les formes indéterminées ?', 'mcq', '["∞ − ∞, 0 × ∞, ∞/∞ et 0/0","0 + ∞ et 1/0","∞ × ∞ et 0 + 0","1^∞ uniquement"]'::jsonb, 0, 'Elles signalent qu’il faut transformer l’écriture, pas qu’il n’y a pas de limite.', 3),
    ('d9e5d782-00e1-501a-9099-cb449632dfbe'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Que dit le théorème des gendarmes ?', 'mcq', '["Si v ≤ u ≤ w et que v et w convergent vers la même limite, u y converge aussi","Une suite majorée converge","Une suite croissante diverge","Deux suites adjacentes ont la même limite"]'::jsonb, 0, 'C’est l’outil de choix face à un terme borné sans limite, comme cos(n).', 4),
    ('99e54c98-1bf8-511c-ab91-cbec709be8e3'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Une suite croissante et majorée par 10 converge vers 10.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le théorème garantit l’existence de la limite, pas sa valeur.', 5),
    ('20a9d8c8-0c55-5b47-a0ae-4e760dd6ec4b'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Une suite croissante non majorée…', 'mcq', '["Diverge vers +∞","Converge","N’a pas de limite","Est constante à partir d’un rang"]'::jsonb, 0, 'C’est le second volet du théorème de la limite monotone.', 6),
    ('476a7280-4416-52f3-a803-dc6ffb5f4e06'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Pour une suite définie par u(n+1) = f(u(n)) qui converge vers ℓ, avec f continue…', 'mcq', '["ℓ vérifie f(ℓ) = ℓ","ℓ vaut 0","ℓ est le premier terme","f(ℓ) = 0"]'::jsonb, 0, 'On cherche les points fixes de f — après avoir démontré la convergence.', 7),
    ('5132d7e5-5174-5e53-ac21-0f199b40bc09'::uuid, '51bd9a16-2126-519e-a166-8fcf19819231'::uuid, 'Le théorème de comparaison par minoration s’applique à une suite qui tend vers +∞.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si u ≥ v à partir d’un rang et v → +∞, alors u → +∞.', 8),
    ('48e13535-8322-5cac-9f23-8fb0909e4009'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Quelle est la limite d’un polynôme en +∞ ?', 'mcq', '["Celle de son terme de plus haut degré","Celle de son terme constant","Toujours +∞","Elle n’existe pas"]'::jsonb, 0, 'On le démontre en factorisant par ce terme dominant.', 1),
    ('3e4ae31a-011a-5fa5-a3fb-fb8f547060c2'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Que vaut la limite de 1/x quand x tend vers 0 par valeurs négatives ?', 'mcq', '["−∞","+∞","0","Elle n’existe pas"]'::jsonb, 0, 'À droite de 0, la limite vaut +∞ : les deux limites latérales diffèrent.', 2),
    ('a81e07f8-338f-51bd-a489-7c3b2734f661'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Quelle technique lève une indétermination du type ∞ − ∞ avec une racine carrée ?', 'mcq', '["La multiplication par l’expression conjuguée","La factorisation par le degré le plus bas","Le théorème des gendarmes","La dérivation"]'::jsonb, 0, 'Elle transforme la différence en quotient, où le terme dominant se factorise.', 3),
    ('a2744424-7533-5958-9819-3c26a9bb5c31'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Une courbe peut-elle couper son asymptote horizontale ?', 'mcq', '["Oui, l’asymptote décrit un comportement à l’infini","Non, jamais","Seulement en un point","Seulement si la fonction est paire"]'::jsonb, 0, 'L’asymptote n’est pas une barrière.', 4),
    ('6c162a35-128e-56d9-b7f1-a52da991ef5b'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Quelle est la condition d’une asymptote oblique d’équation y = ax + b ?', 'mcq', '["f(x) − (ax + b) tend vers 0 en l’infini","f(x) tend vers ax + b","f(x)/x tend vers 0","f est affine"]'::jsonb, 0, 'On détermine a comme limite de f(x)/x, puis b comme limite de f(x) − ax.', 5),
    ('5aa1f653-262e-5ea9-a8ac-ec9148751f04'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Une fonction est continue en a si sa limite en a existe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut de plus que cette limite soit égale à f(a).', 6),
    ('87185049-27d9-54a0-9f3e-19d9a2d0bc73'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Quelle est la limite en +∞ d’une fraction rationnelle ?', 'mcq', '["Celle du quotient des termes de plus haut degré","Celle du quotient des termes constants","Toujours 0","Toujours +∞"]'::jsonb, 0, 'C’est la conséquence directe de la factorisation par le terme dominant.', 7),
    ('100c81c7-4674-5475-8950-d95d68a43c79'::uuid, '94e49829-c662-5c1f-a7d4-60fe30cbd85e'::uuid, 'Le théorème des gendarmes s’applique aux fonctions comme aux suites.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il traite tous les cas où apparaît un facteur borné, comme sin(x)/x en +∞.', 8),
    ('94928609-ebb4-536e-8a0e-e922a5ff36ed'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Quelle est la dérivée de f ∘ u ?', 'mcq', '["u′(x) × f′(u(x))","f′(x) × u′(x)","f′(u′(x))","u(x) × f′(x)"]'::jsonb, 0, 'La dérivée extérieure est évaluée en u(x), et multipliée par u′(x).', 1),
    ('3ce29e65-ed70-59a9-9ffd-961c78599985'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Quelle est la dérivée de e^u ?', 'mcq', '["u′ e^u","e^u","u e^u","e^(u′)"]'::jsonb, 0, 'Le facteur u′ est celui qu’on oublie le plus souvent.', 2),
    ('d1a52a08-ffa4-5e13-9942-264cbf8584e1'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Quelle est la dérivée de ln(u) pour u > 0 ?', 'mcq', '["u′ / u","1 / u","u′ ln(u)","u / u′"]'::jsonb, 0, 'C’est un cas particulier de la dérivée d’une composée.', 3),
    ('fd5e0ad6-5eec-5944-8380-07909ac09e19'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Quelle est la dérivée de √u ?', 'mcq', '["u′ / (2√u)","1 / (2√u)","u′ √u","2u′ √u"]'::jsonb, 0, 'Elle exige u > 0 strictement : la racine n’est pas dérivable en 0.', 4),
    ('a4c70e5f-3b20-5db2-849e-4ed7c2d27db6'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Que vaut la dérivée de (2x − 5)⁴ ?', 'mcq', '["8(2x − 5)³","4(2x − 5)³","(2x − 5)³","8(2x − 5)⁴"]'::jsonb, 0, 'Formule (uⁿ)′ = n u′ uⁿ⁻¹ avec u′ = 2.', 5),
    ('8255006f-d022-508d-9ab3-77ac9583cd03'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'f ∘ u et u ∘ f désignent la même fonction.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’ordre de composition n’est pas symétrique.', 6),
    ('b07c89d2-084b-55d1-b01b-83b8dd969e2b'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'Quelle est la dérivée de (uⁿ) ?', 'mcq', '["n u′ uⁿ⁻¹","n uⁿ⁻¹","u′ uⁿ","n u′ uⁿ"]'::jsonb, 0, 'Cas particulier du théorème de dérivation des composées.', 7),
    ('90e4f9fb-8ece-56b2-8c37-a894dbbe393e'::uuid, '3e24ce43-c21b-5f8c-b01e-ebf1850b93ab'::uuid, 'La formule de la dérivée d’une composée sert aussi à trouver des primitives.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Reconnaître la forme u′ f′(u) est la méthode principale de recherche de primitives.', 8),
    ('147e97f7-443a-5969-ba4f-5284f8fc2e9e'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Une fonction convexe a sa courbe…', 'mcq', '["Au-dessus de chacune de ses tangentes","Au-dessous de chacune de ses tangentes","Confondue avec ses tangentes","Au-dessus de chacune de ses cordes"]'::jsonb, 0, 'Et au-dessous de chacune de ses cordes.', 1),
    ('d8aca554-55e6-55f2-9eb5-f12c11f77993'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Quelle condition sur f″ caractérise la convexité ?', 'mcq', '["f″ positive sur l’intervalle","f″ négative sur l’intervalle","f″ nulle","f″ croissante"]'::jsonb, 0, 'De façon équivalente, f′ est croissante.', 2),
    ('54e2735b-beea-54cd-935f-d4b5602da06b'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Qu’est-ce qu’un point d’inflexion ?', 'mcq', '["Un point où la courbe change de convexité","Un point où la fonction change de variation","Un maximum local","Un point où f s’annule"]'::jsonb, 0, 'En ce point, la tangente traverse la courbe.', 3),
    ('79398ce0-24b5-5334-ae76-8e174697f86e'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'L’annulation de f″ en un point suffit-elle à en faire un point d’inflexion ?', 'mcq', '["Non, il faut un changement de signe de f″","Oui, toujours","Oui, si f est croissante","Non, il faut aussi f′ = 0"]'::jsonb, 0, 'Pour x⁴, f″(0) = 0 alors que la fonction reste convexe partout.', 4),
    ('a7d6b312-b24c-535c-90ec-1d2ce547ec15'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'La fonction ln est convexe sur ]0 ; +∞[.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est concave : sa dérivée 1/x est décroissante.', 5),
    ('be79e85b-697e-5cc1-95d6-97d3fa684f8c'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Quelle inégalité la convexité de l’exponentielle permet-elle d’établir ?', 'mcq', '["e^x ≥ x + 1 pour tout réel x","e^x ≤ x + 1","e^x ≥ x²","ln(x) ≤ x"]'::jsonb, 0, 'La courbe est au-dessus de sa tangente en 0, d’équation y = x + 1.', 6),
    ('90e8fe99-fec3-50c5-95fe-ea6474dbd253'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Une fonction affine est à la fois convexe et concave.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa courbe est confondue avec ses tangentes : f″ est nulle.', 7),
    ('5b854196-2442-54d7-b25d-f785b27a4340'::uuid, 'fa831794-f2f8-558c-87a4-8730f05d1306'::uuid, 'Une fonction décroissante peut-elle être convexe ?', 'mcq', '["Oui, variation et convexité sont indépendantes","Non, jamais","Oui, seulement sur un intervalle borné","Seulement si elle est positive"]'::jsonb, 0, 'Confondre les deux informations est l’erreur la plus fréquente.', 8),
    ('e76e2a7d-f6a8-566b-aa91-6cc9ee8a17c6'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Quand une fonction est-elle continue en a ?', 'mcq', '["Quand sa limite en a existe et vaut f(a)","Quand elle est définie en a","Quand elle est dérivable en a","Quand elle est croissante en a"]'::jsonb, 0, 'La simple existence de la limite ne suffit pas.', 1),
    ('25254462-aacb-5ccd-ad11-4e014c86880f'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Une fonction dérivable en a est-elle continue en a ?', 'mcq', '["Oui, toujours","Non, jamais","Seulement si elle est croissante","Seulement sur un intervalle fermé"]'::jsonb, 0, 'La réciproque est fausse : la valeur absolue est continue en 0 sans y être dérivable.', 2),
    ('1f02485b-8e11-5de6-97df-4d71ab11fab1'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Que garantit le théorème des valeurs intermédiaires ?', 'mcq', '["L’existence d’au moins une solution à f(x) = k","L’unicité de la solution","La valeur exacte de la solution","La dérivabilité de f"]'::jsonb, 0, 'L’unicité demande en plus la stricte monotonie.', 3),
    ('e4b19cbf-c270-5b31-87ee-f2a4a428204b'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Quelle hypothèse ajoute l’unicité au théorème des valeurs intermédiaires ?', 'mcq', '["La stricte monotonie de f","La dérivabilité de f","La positivité de f","La convexité de f"]'::jsonb, 0, 'C’est le corollaire dit théorème de la bijection.', 4),
    ('49d59873-0b3f-50e7-8595-db3910a1758e'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'La fonction partie entière est continue sur ℝ.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est discontinue en chaque entier : c’est le contre-exemple de référence.', 5),
    ('cf08d7b3-79e3-5c8f-8519-206ae8be70d1'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Que fait la méthode de dichotomie ?', 'mcq', '["Elle approche la solution en divisant l’amplitude par deux à chaque étape","Elle démontre l’existence de la solution","Elle calcule la valeur exacte","Elle vérifie la continuité"]'::jsonb, 0, 'Dix étapes suffisent à gagner environ trois décimales.', 6),
    ('fbe34cbd-0f71-5b8b-8d61-6e460d83fda4'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Le théorème de la bijection s’applique-t-il sur un intervalle ouvert ou infini ?', 'mcq', '["Oui, en remplaçant les valeurs aux bornes par les limites","Non, uniquement sur un segment fermé","Oui, sans aucune adaptation","Seulement si f est bornée"]'::jsonb, 0, 'C’est l’extension usuelle dans les exercices.', 7),
    ('b89cc24d-44b5-5fb6-8b05-a5bac3032f0d'::uuid, '4acff6c2-93f4-55bc-915f-ae3d797b958d'::uuid, 'Les quotients de fonctions continues sont continus partout.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Là où le dénominateur ne s’annule pas.', 8),
    ('21c5c9bd-2f09-5ee6-b521-55d1386c889d'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Quel est l’ensemble de définition de la fonction ln ?', 'mcq', '["]0 ; +∞[","ℝ","[0 ; +∞[","ℝ privé de 0"]'::jsonb, 0, 'Vérifier la condition d’existence est l’oubli le plus sanctionné du chapitre.', 1),
    ('297de554-6a8c-59a4-8eef-d611be8bb8af'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Que vaut ln(ab) pour a et b strictement positifs ?', 'mcq', '["ln a + ln b","ln a × ln b","ln(a) ln(b)","ln(a + b)"]'::jsonb, 0, 'C’est la relation fondamentale : le produit devient somme.', 2),
    ('f1433f39-9c70-5707-8cde-42a91b584cc7'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'ln(a + b) est-il égal à ln a + ln b ?', 'mcq', '["Non, cette égalité est fausse","Oui, toujours","Oui, si a et b sont positifs","Oui, si a = b"]'::jsonb, 0, 'C’est l’erreur la plus fréquente du chapitre.', 3),
    ('637f4d86-8c12-54d1-b235-d40bd149104f'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Que vaut ln(e) ?', 'mcq', '["1","0","e","Indéfini"]'::jsonb, 0, 'Et ln(1) = 0 : ce sont les deux valeurs de référence.', 4),
    ('e512fb6f-87a9-511b-a9a0-7e65c5418b00'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Comment résoudre 2^n > 1000 ?', 'mcq', '["En passant au logarithme : n ln 2 > ln 1000","En divisant par 2","En élevant au carré","En dérivant"]'::jsonb, 0, 'Le logarithme fait descendre l’exposant.', 5),
    ('4613bea2-5090-5aef-8f3e-5ff867f0686c'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'La courbe de ln admet une asymptote verticale en 0.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'ln(x) tend vers −∞ quand x tend vers 0 par valeurs positives.', 6),
    ('8b72c9bb-edf8-5c92-a5e6-a3f1e9b05f8f'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Quelle relation lie ln et exponentielle ?', 'mcq', '["Ce sont des fonctions réciproques : e^(ln x) = x pour x > 0","Ce sont des fonctions égales","ln est la dérivée de l’exponentielle","ln est l’opposée de l’exponentielle"]'::jsonb, 0, 'Leurs courbes sont symétriques par rapport à la droite d’équation y = x.', 7),
    ('86cfc8dd-0a42-542d-8b2d-6f005a6f4855'::uuid, '54be3af3-24e8-5da6-b604-6e12219eb94b'::uuid, 'Que vaut ln(a^n) ?', 'mcq', '["n ln a","ln(a)^n","a ln n","n + ln a"]'::jsonb, 0, 'La puissance devient un produit : c’est ce qui rend les exposants calculables.', 8),
    ('20e2a211-ec96-59a6-a809-7d8e0dbfdc9f'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle est la dérivée de ln(x) ?', 'mcq', '["1/x","ln(x)/x","x","−1/x²"]'::jsonb, 0, 'Strictement positive sur ]0 ; +∞[, elle prouve la stricte croissance de ln.', 1),
    ('557e5f80-65b3-524a-ae08-e932906cf5d6'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle est la limite de ln(x) quand x tend vers 0 par valeurs positives ?', 'mcq', '["−∞","+∞","0","1"]'::jsonb, 0, 'D’où l’asymptote verticale d’équation x = 0.', 2),
    ('0e080a38-1dce-50fb-99bf-2e2e92e687e3'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Que vaut la limite de ln(x)/x en +∞ ?', 'mcq', '["0","+∞","1","Elle n’existe pas"]'::jsonb, 0, 'C’est la croissance comparée : la puissance l’emporte sur le logarithme.', 3),
    ('1808dea1-71e4-5a3e-ab03-f01bc47805a8'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle est la dérivée de ln(u) pour u strictement positive ?', 'mcq', '["u′ / u","1 / u","u / u′","u′ ln(u)"]'::jsonb, 0, 'Il faut d’abord déterminer l’ensemble où u > 0.', 4),
    ('3096dd55-a0b5-516d-8733-fef82c264452'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle est la limite de x ln(x) quand x tend vers 0 par valeurs positives ?', 'mcq', '["0","−∞","+∞","1"]'::jsonb, 0, 'Encore une croissance comparée, à connaître par cœur.', 5),
    ('0e6cc141-cfbe-5141-9345-3f15e876f778'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle est l’équation de la tangente à la courbe de ln au point d’abscisse 1 ?', 'mcq', '["y = x − 1","y = x","y = x + 1","y = 1"]'::jsonb, 0, 'ln(1) = 0 et ln′(1) = 1.', 6),
    ('33f857b4-e816-525e-9428-661dfbd92a96'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'La fonction ln est concave sur ]0 ; +∞[.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa dérivée seconde vaut −1/x², strictement négative.', 7),
    ('82713f39-09c9-5741-b9b3-f06f48819d51'::uuid, '9ddf7424-ab72-57b8-afeb-38d39acd0635'::uuid, 'Quelle inégalité découle de la concavité de ln ?', 'mcq', '["ln(x) ≤ x − 1 pour tout x > 0","ln(x) ≥ x − 1","ln(x) ≤ x","ln(x) ≥ 0"]'::jsonb, 0, 'La courbe est au-dessous de sa tangente en 1.', 8),
    ('937de976-c4fb-560e-9062-7bb4b8239147'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Quelle est la dérivée de cos(x) ?', 'mcq', '["−sin(x)","sin(x)","cos(x)","−cos(x)"]'::jsonb, 0, 'Le signe moins est l’oubli classique du chapitre.', 1),
    ('e70ce48d-39da-5390-8c06-a67605ca66cf'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Quelle est la période des fonctions cosinus et sinus ?', 'mcq', '["2π","π","π/2","1"]'::jsonb, 0, 'C’est elle qui permet de réduire l’intervalle d’étude.', 2),
    ('f299de33-f5ac-505e-a0a2-92b212ca484c'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'La fonction sinus est…', 'mcq', '["Impaire","Paire","Ni paire ni impaire","Périodique de période π"]'::jsonb, 0, 'sin(−x) = −sin(x) : sa courbe est symétrique par rapport à l’origine.', 3),
    ('01281006-5e81-50c7-b97f-cb5bbd48bb3d'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Que vaut la limite de sin(x)/x quand x tend vers 0 ?', 'mcq', '["1","0","+∞","Elle n’existe pas"]'::jsonb, 0, 'C’est le nombre dérivé de sinus en 0.', 4),
    ('27eccb1e-5a03-55f5-9e40-6e95abf71ec1'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Les fonctions cosinus et sinus ont-elles une limite en +∞ ?', 'mcq', '["Non, elles oscillent indéfiniment","Oui, elles tendent vers 0","Oui, elles tendent vers 1","Oui, vers +∞"]'::jsonb, 0, 'D’où le recours au théorème des gendarmes pour sin(x)/x en +∞.', 5),
    ('cc082d9a-d713-5a5b-a713-7fe148f0a289'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Quelle est la dérivée de sin(ωx) ?', 'mcq', '["ω cos(ωx)","cos(ωx)","−ω cos(ωx)","ω sin(ωx)"]'::jsonb, 0, 'Application directe de la dérivée d’une composée.', 6),
    ('e3f59337-b4c5-5b34-afc8-dc8d87ac0e58'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'L’équation cos(x) = cos(a) admet combien de familles de solutions ?', 'mcq', '["Deux : x = a + 2kπ et x = −a + 2kπ","Une seule","Trois","Aucune"]'::jsonb, 0, 'Oublier la seconde famille est l’erreur la plus fréquente.', 7),
    ('e148617b-ca54-50e2-9100-2a704d9c9ade'::uuid, '1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Que vaut cos²x + sin²x ?', 'mcq', '["1","0","2","cos(2x)"]'::jsonb, 0, 'C’est la relation fondamentale de la trigonométrie.', 8),
    ('f17baa23-db43-53e7-bd07-209873d0b2d5'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Qu’est-ce qu’une primitive F de f sur un intervalle ?', 'mcq', '["Une fonction dérivable telle que F′ = f","Une fonction telle que f′ = F","La dérivée seconde de f","L’intégrale de f entre 0 et x uniquement"]'::jsonb, 0, 'Toute fonction continue sur un intervalle y admet des primitives.', 1),
    ('eaa6df2b-0f2c-5b58-9ada-0eb519d9cedd'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'De combien les primitives d’une même fonction diffèrent-elles ?', 'mcq', '["D’une constante","D’un facteur multiplicatif","D’une fonction affine","Elles ne diffèrent pas"]'::jsonb, 0, 'C’est ce qui rend nécessaire une condition initiale pour en désigner une.', 2),
    ('ab7e588d-a318-577a-8bdc-fd6281fc3a88'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Quelle est une primitive de 1/x sur ]0 ; +∞[ ?', 'mcq', '["ln(x)","1/x²","−1/x²","x ln(x)"]'::jsonb, 0, 'Sur un intervalle contenant des négatifs, on écrit ln|x|.', 3),
    ('4e49c34d-e36b-5f33-a80a-e5c8c0fcb626'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Quelle est une primitive de la forme u′/u ?', 'mcq', '["ln|u|","u²/2","1/u","u′ ln(u)"]'::jsonb, 0, 'C’est la lecture inverse de la dérivée de ln(u).', 4),
    ('1481897e-2daa-5708-a5ba-7b7fef03dcc4'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Quelles sont les solutions de l’équation différentielle y′ = a y ?', 'mcq', '["Les fonctions x ↦ C e^(a x)","Les fonctions x ↦ a x + C","Les fonctions x ↦ C ln(a x)","La seule fonction nulle"]'::jsonb, 0, 'C’est l’équation de toute évolution proportionnelle à la quantité présente.', 5),
    ('443f2bb4-5e00-571a-9e6c-d4972bf139d9'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Comment résout-on y′ = a y + b ?', 'mcq', '["On cherche une solution particulière constante, puis on ajoute les solutions sans second membre","On intègre directement les deux membres","On dérive l’équation","On pose y = 0"]'::jsonb, 0, 'La solution particulière est y = −b/a.', 6),
    ('a0006798-dd8f-5399-91f0-de475fa475d4'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Une équation différentielle admet une unique solution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle admet une famille de solutions ; c’est la condition initiale qui en sélectionne une.', 7),
    ('a0abee67-edf0-5256-9688-6126abb23f65'::uuid, 'd694f748-9c7a-5733-a537-738e33a7fadb'::uuid, 'Quelle est une primitive de u′ e^u ?', 'mcq', '["e^u","u e^u","e^u / u","u′ e^u"]'::jsonb, 0, 'Lecture inverse de la dérivée d’une exponentielle composée.', 8),
    ('644894e0-367b-5862-8bf1-e2eaf0dc2d5b'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Que vaut l’intégrale de a à b de f, si F est une primitive de f ?', 'mcq', '["F(b) − F(a)","F(a) − F(b)","F(b) × F(a)","F(b − a)"]'::jsonb, 0, 'Le résultat ne dépend pas de la primitive choisie : la constante s’élimine.', 1),
    ('762d45d7-8c7f-58e9-9968-7fd8689a0c47'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Une intégrale est-elle toujours positive ?', 'mcq', '["Non, elle est négative si la fonction est négative","Oui, c’est une aire","Oui, si les bornes sont dans l’ordre croissant","Non, elle est toujours négative"]'::jsonb, 0, 'C’est une aire algébrique, pas une aire géométrique.', 2),
    ('99a6e4f6-2215-57d2-a5c3-c236f086352d'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Que dit la relation de Chasles pour les intégrales ?', 'mcq', '["De a à b, plus de b à c, égale de a à c","L’intégrale d’une somme est la somme des intégrales","Échanger les bornes change le signe","L’intégrale d’un produit est le produit des intégrales"]'::jsonb, 0, 'Elle permet de découper un intervalle d’intégration.', 3),
    ('fdd3bcef-8205-5077-b39a-46ffb20c245d'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Comment calcule-t-on la valeur moyenne de f sur [a ; b] ?', 'mcq', '["En divisant l’intégrale par (b − a)","En multipliant l’intégrale par (b − a)","En prenant (f(a) + f(b))/2","En dérivant l’intégrale"]'::jsonb, 0, 'C’est la hauteur du rectangle de même aire que le domaine sous la courbe.', 4),
    ('7b0b3b05-6339-56d9-b497-09b4af8c9608'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Quelle est la formule de l’intégration par parties ?', 'mcq', '["∫ u′v = [uv] − ∫ u v′","∫ uv = [u′v] − ∫ u′ v","∫ u′v = [uv] + ∫ u v′","∫ uv′ = [u′v′]"]'::jsonb, 0, 'On l’emploie quand l’intégrande est un produit dont un facteur se simplifie en dérivant.', 5),
    ('5149dbbe-da0c-5eec-a103-b0aeefd35ed2'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Comment calcule-t-on l’aire entre deux courbes sur [a ; b] ?', 'mcq', '["Par l’intégrale de la différence, en identifiant d’abord la courbe du dessus","Par la somme des deux intégrales","Par le produit des deux intégrales","Par la différence des valeurs moyennes"]'::jsonb, 0, 'Si les courbes se croisent, il faut découper l’intervalle.', 6),
    ('ca19469f-2aab-574f-8475-e15ea4df228b'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Échanger les bornes d’une intégrale change son signe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une conséquence directe de la formule F(b) − F(a).', 7),
    ('1dcd26f8-8599-535b-bba2-a878c9f6256b'::uuid, '85c45745-252d-5305-9e93-a0c9a8904265'::uuid, 'Que faire quand aucune primitive ne s’exprime simplement ?', 'mcq', '["Approcher l’intégrale par la méthode des rectangles ou des trapèzes","Conclure que l’intégrale n’existe pas","Dériver la fonction","Changer les bornes"]'::jsonb, 0, 'La précision croît avec le nombre de subdivisions.', 8),
    ('a02e7cec-d86a-5bb8-9f24-ca5a8bb84d0e'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Qu’est-ce qu’une épreuve de Bernoulli ?', 'mcq', '["Une expérience aléatoire à deux issues","Une expérience répétée n fois","Une variable aléatoire continue","Un tirage sans remise"]'::jsonb, 0, 'Le succès de probabilité p, l’échec de probabilité 1 − p.', 1),
    ('5544cb10-2de6-5340-8d1a-9c3353fd81ad'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Que compte une variable aléatoire suivant la loi binomiale B(n ; p) ?', 'mcq', '["Le nombre de succès sur n épreuves indépendantes","Le rang du premier succès","La durée d’attente","La probabilité d’un succès"]'::jsonb, 0, 'Elle ne tient pas compte de l’ordre d’apparition des succès.', 2),
    ('ab1f8711-7c61-5967-ba4a-4f6ef36f608d'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Quelle est l’expression de P(X = k) pour X suivant B(n ; p) ?', 'mcq', '["C(n,k) p^k (1−p)^(n−k)","p^k (1−p)^(n−k)","C(n,k) p^n","n p^k"]'::jsonb, 0, 'Le coefficient C(n,k) compte les chemins réalisant exactement k succès.', 3),
    ('8151d7c5-b3af-5a95-8e74-282e4a503811'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Que vaut l’espérance d’une variable suivant B(n ; p) ?', 'mcq', '["n p","p","n p (1−p)","√(n p)"]'::jsonb, 0, 'Sur 100 lancers d’une pièce équilibrée, on attend 50 piles.', 4),
    ('ccf24c52-9789-57ae-9e78-b9b25826b389'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Que vaut la variance d’une loi binomiale B(n ; p) ?', 'mcq', '["n p (1−p)","n p","p(1−p)","√(n p (1−p))"]'::jsonb, 0, 'L’écart-type en est la racine carrée.', 5),
    ('b8ec2839-0dd9-5dca-a7a9-4942f9515a29'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Un tirage sans remise dans une petite population donne des épreuves indépendantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le piège le plus fréquent des sujets de bac.', 6),
    ('a48b2bbe-c4b0-5663-a5c0-4207c0c287e5'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Comment calcule-t-on P(X ≥ k) ?', 'mcq', '["1 − P(X ≤ k−1)","1 − P(X ≤ k)","P(X ≤ k) − 1","P(X = k) + P(X = k+1)"]'::jsonb, 0, 'Le passage par l’événement contraire est l’automatisme à acquérir.', 7),
    ('55696fb9-3776-53be-b254-1a9b8f50648a'::uuid, 'eab822a5-4e2a-569d-ab3c-7b5c4b3ec0a8'::uuid, 'Sur un arbre pondéré, la probabilité d’un chemin est…', 'mcq', '["Le produit des probabilités de ses branches","La somme des probabilités de ses branches","La plus petite de ses probabilités","La moyenne de ses probabilités"]'::jsonb, 0, 'La probabilité d’un événement est, elle, la somme des chemins qui le réalisent.', 8),
    ('e73c399f-7046-51e8-86b5-9a2acdd19193'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'L’égalité E(X + Y) = E(X) + E(Y) exige-t-elle l’indépendance ?', 'mcq', '["Non, elle est toujours vraie","Oui, toujours","Oui, sauf pour la loi binomiale","Elle est fausse en général"]'::jsonb, 0, 'L’espérance est additive sans condition : c’est ce qui la distingue de la variance.', 1),
    ('a86407b4-5032-5aaf-85cf-0fd327244330'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Que vaut V(aX + b) ?', 'mcq', '["a² V(X)","a V(X) + b","a V(X)","a² V(X) + b²"]'::jsonb, 0, 'Le coefficient est au carré et la constante disparaît.', 2),
    ('ba03ae72-25f1-59bd-910b-e73676b45705'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Sous quelle condition a-t-on V(X + Y) = V(X) + V(Y) ?', 'mcq', '["Si X et Y sont indépendantes","Toujours","Si X et Y ont la même loi","Si X et Y sont positives"]'::jsonb, 0, 'C’est l’erreur la plus sanctionnée du chapitre.', 3),
    ('9efc7538-2832-5f17-8824-5d3a4cab18ff'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Que vaut l’écart-type de la moyenne empirique d’un échantillon de taille n ?', 'mcq', '["σ/√n","σ/n","σ√n","σ"]'::jsonb, 0, 'La dispersion décroît en 1/√n, donc lentement.', 4),
    ('d98aac5f-0e9f-5383-b968-6287dcd39a91'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Que vaut l’espérance de la moyenne empirique d’un échantillon ?', 'mcq', '["μ, l’espérance de la variable de départ","μ/n","n μ","0"]'::jsonb, 0, 'La moyenne empirique est sans biais : elle ne se trompe pas systématiquement.', 5),
    ('0d426fba-ca2a-5cc9-8a29-94c28d0e0cdf'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Pour diviser par deux l’écart-type de la moyenne empirique, il faut…', 'mcq', '["Quadrupler la taille de l’échantillon","Doubler la taille de l’échantillon","Diviser la taille par deux","Changer de variable"]'::jsonb, 0, 'C’est la conséquence directe du √n, et ce qui rend les sondages coûteux.', 6),
    ('ccdb641b-75ee-549c-9857-16502edbd05b'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Une variable de loi binomiale B(n ; p) est une somme de n variables de Bernoulli indépendantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On en déduit immédiatement E = n p et V = n p (1 − p).', 7),
    ('a7b39a1e-db50-543d-8afe-6aa67bc323ef'::uuid, '74f567ba-680b-5396-a5d0-bab4cb234af6'::uuid, 'Dans quelle unité s’exprime l’écart-type ?', 'mcq', '["La même que la variable","Le carré de celle de la variable","Sans unité","En pourcentage"]'::jsonb, 0, 'C’est ce qui le rend plus lisible que la variance.', 8),
    ('7c3745a6-7acf-547b-b880-5cf056bc38f1'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Que dit l’inégalité de Markov ?', 'mcq', '["P(X ≥ a) ≤ E(X)/a pour X positive et a > 0","P(X ≥ a) ≤ V(X)/a²","P(X = a) ≤ E(X)","E(X) ≤ a P(X ≥ a)"]'::jsonb, 0, 'Elle n’utilise que l’espérance, ce qui la rend générale mais peu précise.', 1),
    ('02ba0b2d-ac56-5743-a101-2d99fb01756b'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Que majore l’inégalité de Bienaymé-Tchebychev ?', 'mcq', '["La probabilité de s’écarter de la moyenne d’au moins δ","L’espérance d’une variable positive","La variance d’une somme","La taille d’un échantillon"]'::jsonb, 0, 'Le majorant est V/δ² : plus la variance est faible, plus la variable est concentrée.', 2),
    ('82d6d570-76cf-5698-a36d-99056fe697e9'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'L’inégalité de Bienaymé-Tchebychev suppose-t-elle une loi particulière ?', 'mcq', '["Non, elle vaut pour toute loi","Oui, la loi binomiale","Oui, une loi symétrique","Oui, une loi continue"]'::jsonb, 0, 'C’est sa force ; sa faiblesse est d’être grossière.', 3),
    ('f0c9e4ac-aa07-5a94-a020-a2e55fce7a29'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Que devient le majorant de P(|M − μ| ≥ δ) quand n augmente ?', 'mcq', '["Il tend vers 0","Il tend vers 1","Il reste constant","Il augmente"]'::jsonb, 0, 'Le majorant vaut σ²/(n δ²) : c’est la loi des grands nombres.', 4),
    ('be715d4e-55fd-5d2b-bc52-67c9c1f26a08'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Que dit la loi des grands nombres ?', 'mcq', '["La moyenne empirique se concentre autour de l’espérance quand n grandit","Les écarts passés finissent par se compenser","Toute suite de tirages est équilibrée","La variance tend vers l’espérance"]'::jsonb, 0, 'Elle porte sur la moyenne, jamais sur une répétition particulière.', 5),
    ('9b373603-bf24-53b0-b57e-acf53843a27e'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Après dix « pile » consécutifs, la probabilité de « face » au lancer suivant augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’erreur du joueur : la pièce n’a pas de mémoire.', 6),
    ('a5baf981-ceb2-58b4-8d83-6ad89ad7f5f2'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Pourquoi peut-on dimensionner un sondage sans connaître la proportion p ?', 'mcq', '["Parce que p(1 − p) est majoré par 1/4","Parce que la variance est nulle","Parce que n est fixé par la loi","Parce que p vaut toujours 0,5"]'::jsonb, 0, 'Ce majorant rend le calcul de la taille d’échantillon possible à l’avance.', 7),
    ('8662581c-bbb8-5ae6-9e3c-84323d40f40e'::uuid, '09c72318-9e8c-5b02-983f-1d6d34f550d9'::uuid, 'Dans le cas d’une loi de Bernoulli, que représente la moyenne empirique ?', 'mcq', '["La fréquence observée de succès","Le nombre total de succès","L’écart-type","La probabilité théorique"]'::jsonb, 0, 'La loi des grands nombres dit alors que la fréquence tend vers la probabilité.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('maths-complementaires', 'maths-expertes', 'maths');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('maths-complementaires', 'maths-expertes', 'maths')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 255 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 255 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
